const data = [
  // Biome 100
  {animalId: 101, da: {name: 'Akhal-Teke', desc: 'Akhal-Teke betragtes som en af verdens mest elegante hesteracer med sit metallisk skinnende pels. Disse heste fra Turkmenistan er udholdende, hurtige og ekstremt modstandsdygtige. I din zoo traver de stolt gennem indhegningen og tiltr\u00e6kker alle blikke med deres fornemme udseende.'},
   nl: {name: 'Akhal-Teke', desc: 'De Akhal-Teke wordt beschouwd als een van de meest elegante paardenrassen ter wereld, bekend om zijn metaalglanzende vacht. Deze paarden uit Turkmenistan zijn duurzaam, snel en extreem veerkrachtig. In jouw dierentuin draven ze trots door het verblijf en trekken ze ieders aandacht met hun edele verschijning.'},
   fr: {name: 'Akhal-T\u00e9k\u00e9', desc: 'L\'Akhal-T\u00e9k\u00e9 est consid\u00e9r\u00e9 comme l\'une des races de chevaux les plus \u00e9l\u00e9gantes au monde, connu pour sa robe au reflet m\u00e9tallique. Ces chevaux du Turkm\u00e9nistan sont endurants, rapides et extr\u00eamement r\u00e9sistants. Dans ton zoo, ils trottent fi\u00e8rement dans l\'enclos et attirent tous les regards par leur noble apparence.'},
   es: {name: 'Ahal-Teke', desc: 'El Ahal-Teke es considerado una de las razas de caballos m\u00e1s elegantes del mundo, conocido por su pelaje con brillo met\u00e1lico. Estos caballos de Turkmenist\u00e1n son resistentes, veloces y extremadamente robustos. En tu zoo, trotan con orgullo por el recinto y atraen todas las miradas con su noble apariencia.'}},
  {animalId: 102, da: {name: 'Angorakanin', desc: 'Angorakaninen er kendt for sin ekstremt bl\u00f8de og lange pels, der kan blive op til 10 cm lang. Denne charmerende race stammer oprindeligt fra Ankara i Tyrkiet. I din zoo hopper den rundt i indhegningen og begejstrer bes\u00f8gende med sit fluffy udseende.'},
   nl: {name: 'Angorakonijn', desc: 'Het angorakonijn staat bekend om zijn extreem zachte en lange vacht, die tot 10 cm lang kan worden. Dit charmante ras stamt oorspronkelijk uit Ankara in Turkije. In jouw dierentuin huppelt het door het verblijf en betovert bezoekers met zijn pluizige verschijning.'},
   fr: {name: 'Lapin angora', desc: 'Le lapin angora est c\u00e9l\u00e8bre pour sa fourrure extr\u00eamement douce et longue, pouvant atteindre 10 cm. Cette race charmante est originaire d\'Ankara en Turquie. Dans ton zoo, il sautille dans son enclos et enchante les visiteurs avec son apparence duveteuse.'},
   es: {name: 'Conejo angora', desc: 'El conejo angora es famoso por su pelaje extremadamente suave y largo, que puede alcanzar los 10 cm. Esta encantadora raza es originaria de Ankara, Turqu\u00eda. En tu zoo, salta alegremente por el recinto y fascina a los visitantes con su aspecto esponjoso.'}},
  {animalId: 103, da: {name: 'B\u00e6ver', desc: 'B\u00e6veren er naturens dygtigste ingeni\u00f8r og bygger imponerende d\u00e6mninger af tr\u00e6 og mudder. Med sin flade, sk\u00e6llede hale og sine st\u00e6rke t\u00e6nder kan den f\u00e6lde selv store tr\u00e6er. I din zoo sv\u00f8mmer den flittigt i sit vandbassin og arbejder konstant p\u00e5 at forbedre sin bolig.'},
   nl: {name: 'Bever', desc: 'De bever is de bekwaamste ingenieur van de natuur en bouwt indrukwekkende dammen van hout en modder. Met zijn platte, geschubde staart en sterke tanden kan hij zelfs grote bomen vellen. In jouw dierentuin zwemt hij ijverig in zijn waterbassin en werkt constant aan het verbeteren van zijn onderkomen.'},
   fr: {name: 'Castor', desc: 'Le castor est le plus habile ing\u00e9nieur de la nature, construisant des barrages impressionnants en bois et en boue. Avec sa queue plate et \u00e9cailleuse et ses dents puissantes, il peut abattre m\u00eame de grands arbres. Dans ton zoo, il nage activement dans son bassin et travaille sans cesse \u00e0 am\u00e9liorer son habitat.'},
   es: {name: 'Castor', desc: 'El castor es el ingeniero m\u00e1s h\u00e1bil de la naturaleza, construyendo impresionantes represas de madera y barro. Con su cola plana y escamosa y sus fuertes dientes, puede derribar incluso \u00e1rboles grandes. En tu zoo, nada activamente en su estanque y trabaja constantemente en mejorar su hogar.'}},
  {animalId: 104, da: {name: 'Bl\u00e5fodet sule', desc: 'Den bl\u00e5fodede sule er ber\u00f8mt for sine i\u00f8jnefaldende bl\u00e5 f\u00f8dder, som spiller en vigtig rolle i parringsdansen. Denne havfugl lever langs Stillehavets kyster og er en fremragende dykker. I din zoo vader den stolt rundt og viser sine bl\u00e5 f\u00f8dder frem for alle bes\u00f8gende.'},
   nl: {name: 'Blauwvoetgent', desc: 'De blauwvoetgent is beroemd om zijn opvallende blauwe poten, die een belangrijke rol spelen bij de paringsdans. Deze zeevogel leeft langs de kusten van de Stille Oceaan en is een uitstekende duiker. In jouw dierentuin waggelt hij trots rond en laat zijn blauwe poten aan alle bezoekers zien.'},
   fr: {name: 'Fou \u00e0 pieds bleus', desc: 'Le fou \u00e0 pieds bleus est c\u00e9l\u00e8bre pour ses pattes d\'un bleu \u00e9clatant, qui jouent un r\u00f4le crucial dans la danse nuptiale. Cet oiseau marin vit le long des c\u00f4tes du Pacifique et est un excellent plongeur. Dans ton zoo, il se pavane fi\u00e8rement et exhibe ses pattes bleues devant tous les visiteurs.'},
   es: {name: 'Alcatraz patiazul', desc: 'El alcatraz patiazul es famoso por sus llamativas patas azules, que juegan un papel importante en la danza de apareamiento. Esta ave marina vive a lo largo de las costas del Pac\u00edfico y es un excelente buceador. En tu zoo, se pavonea orgullosamente mostrando sus patas azules a todos los visitantes.'}},
  {animalId: 105, da: {name: 'D\u00e5dyr', desc: 'D\u00e5dyret er kendt for sin smukke, plettet pels og sine karakteristiske skovlformede gevirer. Det lever naturligt i europ\u00e6iske skove og parker. I din zoo gr\u00e6sser det fredeligt p\u00e5 engene og charmer bes\u00f8gende med sin elegante fremtoning.'},
   nl: {name: 'Damhert', desc: 'Het damhert staat bekend om zijn prachtige, gevlekte vacht en zijn karakteristieke schopvormige gewei. Het leeft van nature in Europese bossen en parken. In jouw dierentuin graast het vredig op de weiden en betovert bezoekers met zijn elegante verschijning.'},
   fr: {name: 'Daim', desc: 'Le daim est connu pour son magnifique pelage tachet\u00e9 et ses bois caract\u00e9ristiques en forme de pelle. Il vit naturellement dans les for\u00eats et parcs europ\u00e9ens. Dans ton zoo, il broute paisiblement dans les prairies et charme les visiteurs par son allure \u00e9l\u00e9gante.'},
   es: {name: 'Gamo', desc: 'El gamo es conocido por su hermoso pelaje moteado y sus caracter\u00edsticos cuernos en forma de pala. Vive de forma natural en bosques y parques europeos. En tu zoo, pasta tranquilamente en las praderas y encanta a los visitantes con su elegante porte.'}},
  {animalId: 106, da: {name: 'Mara', desc: 'Maraen er en stor gnaver fra Patagonien, der ligner en blanding af en hare og et lille hjort. Den kan l\u00f8be med hastigheder op til 45 km/t og lever i par for livet. I din zoo hopper den livligt rundt i indhegningen og underholder bes\u00f8gende med sine akrobatiske spring.'},
   nl: {name: 'Mara', desc: 'De mara is een groot knaagdier uit Patagoni\u00eb dat lijkt op een kruising tussen een haas en een klein hert. Hij kan snelheden tot 45 km/u bereiken en leeft in levenslange paren. In jouw dierentuin springt hij vrolijk door het verblijf en vermaakt bezoekers met zijn acrobatische sprongen.'},
   fr: {name: 'Mara de Patagonie', desc: 'Le mara de Patagonie est un grand rongeur ressemblant \u00e0 un croisement entre un li\u00e8vre et un petit cerf. Il peut atteindre des vitesses de 45 km/h et vit en couples pour la vie. Dans ton zoo, il bondit joyeusement dans l\'enclos et divertit les visiteurs avec ses sauts acrobatiques.'},
   es: {name: 'Mara patag\u00f3nica', desc: 'La mara patag\u00f3nica es un gran roedor que parece un cruce entre una liebre y un peque\u00f1o ciervo. Puede alcanzar velocidades de hasta 45 km/h y vive en parejas de por vida. En tu zoo, salta alegremente por el recinto y entretiene a los visitantes con sus saltos acrob\u00e1ticos.'}},
  {animalId: 107, da: {name: 'K\u00e6mpepanda', desc: 'K\u00e6mpepandaen er et af verdens mest elskede dyr med sin ikoniske sorte og hvide pels. Den lever i de kinesiske bjergskove og spiser n\u00e6sten udelukkende bambus. I din zoo sidder den afslappet og tygger bambus, mens bes\u00f8gende beundrer dens charmerende udseende.'},
   nl: {name: 'Reuzenpanda', desc: 'De reuzenpanda is een van de meest geliefde dieren ter wereld met zijn iconische zwart-witte vacht. Hij leeft in de Chinese bergbossen en eet bijna uitsluitend bamboe. In jouw dierentuin zit hij ontspannen bamboe te kauwen terwijl bezoekers zijn charmante verschijning bewonderen.'},
   fr: {name: 'Grand panda', desc: 'Le grand panda est l\'un des animaux les plus aim\u00e9s au monde avec son pelage iconique noir et blanc. Il vit dans les for\u00eats montagneuses de Chine et se nourrit presque exclusivement de bambou. Dans ton zoo, il est assis tranquillement \u00e0 m\u00e2cher du bambou tandis que les visiteurs admirent son charme irr\u00e9sistible.'},
   es: {name: 'Oso panda gigante', desc: 'El oso panda gigante es uno de los animales m\u00e1s queridos del mundo con su ic\u00f3nico pelaje blanco y negro. Vive en los bosques monta\u00f1osos de China y se alimenta casi exclusivamente de bamb\u00fa. En tu zoo, se sienta relajado comiendo bamb\u00fa mientras los visitantes admiran su encantadora apariencia.'}},
  {animalId: 108, da: {name: 'Hare', desc: 'Haren er et hurtigt og smidigt dyr med lange \u00f8rer og kraftige bagben, der kan n\u00e5 hastigheder p\u00e5 over 70 km/t. Den lever p\u00e5 \u00e5bne marker og enge i Europa. I din zoo springer den energisk rundt og imponerer bes\u00f8gende med sin utrolige hurtighed.'},
   nl: {name: 'Haas', desc: 'De haas is een snel en behendig dier met lange oren en krachtige achterpoten, dat snelheden van meer dan 70 km/u kan bereiken. Hij leeft op open velden en weiden in Europa. In jouw dierentuin sprint hij energiek rond en maakt indruk op bezoekers met zijn ongelooflijke snelheid.'},
   fr: {name: 'Li\u00e8vre', desc: 'Le li\u00e8vre est un animal rapide et agile avec de longues oreilles et des pattes arri\u00e8re puissantes, capable d\'atteindre plus de 70 km/h. Il vit dans les champs ouverts et les prairies d\'Europe. Dans ton zoo, il court \u00e9nergiquement et impressionne les visiteurs par sa vitesse incroyable.'},
   es: {name: 'Liebre', desc: 'La liebre es un animal r\u00e1pido y \u00e1gil con largas orejas y poderosas patas traseras, capaz de alcanzar m\u00e1s de 70 km/h. Vive en campos abiertos y praderas de Europa. En tu zoo, corre en\u00e9rgicamente y asombra a los visitantes con su incre\u00edble velocidad.'}},
  {animalId: 109, da: {name: 'Hushvin', desc: 'Hussvinet er et intelligent og socialt dyr, der har levet sammen med mennesker i tusinder af \u00e5r. Det har en fremragende lugtesans og kan tr\u00e6nes til mange opgaver. I din zoo roder det forn\u00f8jet i mudderet og charmer bes\u00f8gende med sin nysgerrige personlighed.'},
   nl: {name: 'Varken', desc: 'Het varken is een intelligent en sociaal dier dat al duizenden jaren samenleeft met mensen. Het heeft een uitstekend reukvermogen en kan voor veel taken worden getraind. In jouw dierentuin wroet het tevreden in de modder en betovert bezoekers met zijn nieuwsgierige persoonlijkheid.'},
   fr: {name: 'Cochon domestique', desc: 'Le cochon domestique est un animal intelligent et social qui vit aux c\u00f4t\u00e9s des humains depuis des milliers d\'ann\u00e9es. Il poss\u00e8de un odorat exceptionnel et peut \u00eatre dress\u00e9 pour de nombreuses t\u00e2ches. Dans ton zoo, il fouille joyeusement dans la boue et charme les visiteurs par sa personnalit\u00e9 curieuse.'},
   es: {name: 'Cerdo dom\u00e9stico', desc: 'El cerdo dom\u00e9stico es un animal inteligente y social que ha convivido con los humanos durante miles de a\u00f1os. Tiene un sentido del olfato excepcional y puede ser entrenado para muchas tareas. En tu zoo, hurga alegremente en el barro y encanta a los visitantes con su personalidad curiosa.'}},
  {animalId: 110, da: {name: 'Ged', desc: 'Geden er et nysgerrigt og klatrende dyr, der trives i bjergene og har v\u00e6ret tammet i over 10.000 \u00e5r. Den er kendt for sin evne til at klatre i de stejleste terr\u00e6ner. I din zoo klatrer den p\u00e5 klipper og strukturer og underholder bes\u00f8gende med sit legesyge temperament.'},
   nl: {name: 'Geit', desc: 'De geit is een nieuwsgierig en klimlustig dier dat gedijt in de bergen en al meer dan 10.000 jaar gedomesticeerd is. Ze staat bekend om haar vermogen om in de steilste terreinen te klimmen. In jouw dierentuin klimt ze op rotsen en structuren en vermaakt bezoekers met haar speelse karakter.'},
   fr: {name: 'Ch\u00e8vre domestique', desc: 'La ch\u00e8vre domestique est un animal curieux et grimpeur qui prosp\u00e8re en montagne et a \u00e9t\u00e9 domestiqu\u00e9e il y a plus de 10 000 ans. Elle est connue pour sa capacit\u00e9 \u00e0 grimper dans les terrains les plus escarp\u00e9s. Dans ton zoo, elle escalade rochers et structures et divertit les visiteurs par son temp\u00e9rament joueur.'},
   es: {name: 'Cabra dom\u00e9stica', desc: 'La cabra dom\u00e9stica es un animal curioso y trepador que prospera en las monta\u00f1as y ha sido domesticada hace m\u00e1s de 10.000 a\u00f1os. Es conocida por su capacidad de trepar por los terrenos m\u00e1s escarpados. En tu zoo, escala rocas y estructuras y divierte a los visitantes con su temperamento juguet\u00f3n.'}},
  {animalId: 111, da: {name: 'Pataabe', desc: 'Pataaben er den hurtigste primat i verden og kan l\u00f8be med hastigheder op til 55 km/t. Den lever i de afrikanske savanners \u00e5bne landskaber og har lange, slanke lemmer. I din zoo sprinter den imponerende hurtigt gennem indhegningen og fascinerer bes\u00f8gende med sin atletiske krop.'},
   nl: {name: 'Patasaap', desc: 'De patasaap is de snelste primaat ter wereld en kan snelheden tot 55 km/u bereiken. Hij leeft in de open landschappen van de Afrikaanse savanne en heeft lange, slanke ledematen. In jouw dierentuin sprint hij indrukwekkend snel door het verblijf en fascineert bezoekers met zijn atletische bouw.'},
   fr: {name: 'Singe patas', desc: 'Le singe patas est le primate le plus rapide du monde, capable d\'atteindre 55 km/h. Il vit dans les paysages ouverts de la savane africaine et poss\u00e8de des membres longs et \u00e9lanc\u00e9s. Dans ton zoo, il sprinte \u00e0 une vitesse impressionnante dans l\'enclos et fascine les visiteurs par sa silhouette athl\u00e9tique.'},
   es: {name: 'Mono pata', desc: 'El mono pata es el primate m\u00e1s r\u00e1pido del mundo, capaz de alcanzar velocidades de hasta 55 km/h. Vive en los paisajes abiertos de la sabana africana y tiene extremidades largas y esbeltas. En tu zoo, corre a una velocidad impresionante por el recinto y fascina a los visitantes con su cuerpo atl\u00e9tico.'}},
  {animalId: 112, da: {name: 'Jaguarundi', desc: 'Jaguarundien er en lille, slank vildkat fra Central- og Sydamerika med et us\u00e6dvanligt udseende, der minder om en odder. Den er en dygtig j\u00e6ger, der jager b\u00e5de dag og nat. I din zoo sniger den sig elegant gennem vegetationen og fanger bes\u00f8gendes opm\u00e6rksomhed med sine hurtige bev\u00e6gelser.'},
   nl: {name: 'Jaguarundi', desc: 'De jaguarundi is een kleine, slanke wilde kat uit Midden- en Zuid-Amerika met een ongewoon uiterlijk dat doet denken aan een otter. Hij is een bekwame jager die zowel overdag als \'s nachts jaagt. In jouw dierentuin sluipt hij elegant door de vegetatie en trekt de aandacht van bezoekers met zijn snelle bewegingen.'},
   fr: {name: 'Jaguarondi', desc: 'Le jaguarondi est un petit f\u00e9lin \u00e9lanc\u00e9 d\'Am\u00e9rique centrale et du Sud, \u00e0 l\'allure inhabituelle rappelant une loutre. C\'est un chasseur habile qui chasse de jour comme de nuit. Dans ton zoo, il se faufile \u00e9l\u00e9gamment \u00e0 travers la v\u00e9g\u00e9tation et captive les visiteurs par ses mouvements rapides.'},
   es: {name: 'Jaguarund\u00ed', desc: 'El jaguarund\u00ed es un peque\u00f1o felino esbelto de Am\u00e9rica Central y del Sur con una apariencia inusual que recuerda a una nutria. Es un h\u00e1bil cazador que caza tanto de d\u00eda como de noche. En tu zoo, se desliza elegantemente entre la vegetaci\u00f3n y cautiva a los visitantes con sus r\u00e1pidos movimientos.'}},
  {animalId: 113, da: {name: 'Klunketrane', desc: 'Klunketranen er en stor og majest\u00e6tisk fugl fra det sydlige Afrika, kendt for de r\u00f8de k\u00f8dlapper p\u00e5 dens hoved. Den er en af de sj\u00e6ldneste tranearter i verden. I din zoo danser den graci\u00f8st og udf\u00f8rer imponerende parringsdanse, der begejstrer alle bes\u00f8gende.'},
   nl: {name: 'Lelkraan', desc: 'De lelkraan is een grote en majestueuze vogel uit zuidelijk Afrika, bekend om de rode huidlellen op zijn hoofd. Het is een van de zeldzaamste kraanvogelsoorten ter wereld. In jouw dierentuin danst hij sierlijk en voert indrukwekkende paringsdansen uit die alle bezoekers betoveren.'},
   fr: {name: 'Grue caronculée', desc: 'La grue caronculée est un grand oiseau majestueux d\'Afrique australe, reconnaissable aux caroncules rouges sur sa t\u00eate. C\'est l\'une des esp\u00e8ces de grues les plus rares au monde. Dans ton zoo, elle danse gracieusement et ex\u00e9cute des parades nuptiales impressionnantes qui ravissent tous les visiteurs.'},
   es: {name: 'Grulla carunculada', desc: 'La grulla carunculada es una gran ave majestuosa del sur de \u00c1frica, conocida por las car\u00fanculas rojas en su cabeza. Es una de las especies de grullas m\u00e1s raras del mundo. En tu zoo, baila con gracia y realiza impresionantes danzas nupciales que deleitan a todos los visitantes.'}},
  {animalId: 114, da: {name: 'Kortsnabelpigsvin', desc: 'Kortsnabelpigsvindet er et af de f\u00e5 \u00e6gmelkende pattedyr i verden, d\u00e6kket af skarpe pigge. Det lever i Australien og Ny Guinea og bruger sin lange snude til at finde insekter. I din zoo graver det i jorden efter f\u00f8de og fascinerer bes\u00f8gende med sit unikke udseende.'},
   nl: {name: 'Kortsnabelegel', desc: 'De kortsnabelegel is een van de weinige eierleggende zoogdieren ter wereld, bedekt met scherpe stekels. Hij leeft in Australi\u00eb en Nieuw-Guinea en gebruikt zijn lange snuit om insecten te zoeken. In jouw dierentuin graaft hij in de grond naar voedsel en fascineert bezoekers met zijn unieke verschijning.'},
   fr: {name: '\u00c9chidn\u00e9 \u00e0 nez court', desc: 'L\'\u00e9chidn\u00e9 \u00e0 nez court est l\'un des rares mammif\u00e8res ovipares au monde, couvert de piquants ac\u00e9r\u00e9s. Il vit en Australie et en Nouvelle-Guin\u00e9e et utilise son long museau pour trouver des insectes. Dans ton zoo, il creuse le sol \u00e0 la recherche de nourriture et fascine les visiteurs par son apparence unique.'},
   es: {name: 'Equidna de hocico corto', desc: 'El equidna de hocico corto es uno de los pocos mam\u00edferos que ponen huevos, cubierto de afiladas p\u00faas. Vive en Australia y Nueva Guinea y usa su largo hocico para encontrar insectos. En tu zoo, excava en el suelo buscando alimento y fascina a los visitantes con su aspecto \u00fanico.'}},
  {animalId: 115, da: {name: 'Slikkebjørn', desc: 'Slikkebj\u00f8rnen er en us\u00e6dvanlig bj\u00f8rneart fra Indien med lang, stridt pels og en s\u00e6rlig lang tunge til at slikke insekter op. Den er nataktiv og kan h\u00e6nge fra grene som en dovendyr. I din zoo graver den ivrigt efter insekter og underholder bes\u00f8gende med sin sjove adf\u00e6rd.'},
   nl: {name: 'Lippenbeer', desc: 'De lippenbeer is een ongewone beersoort uit India met een lange, ruige vacht en een bijzonder lange tong om insecten op te likken. Hij is nachtactief en kan als een luiaard aan takken hangen. In jouw dierentuin graaft hij gretig naar insecten en vermaakt bezoekers met zijn grappige gedrag.'},
   fr: {name: 'Ours lippu', desc: 'L\'ours lippu est une esp\u00e8ce d\'ours inhabituelle d\'Inde, au pelage long et hirsute et \u00e0 la langue particuli\u00e8rement longue pour l\u00e9cher les insectes. Il est nocturne et peut se suspendre aux branches comme un paresseux. Dans ton zoo, il fouille activement le sol \u00e0 la recherche d\'insectes et amuse les visiteurs par son comportement comique.'},
   es: {name: 'Oso bezudo', desc: 'El oso bezudo es una especie inusual de oso de la India con un pelaje largo y \u00e1spero y una lengua especialmente larga para lamer insectos. Es nocturno y puede colgarse de las ramas como un perezoso. En tu zoo, excava activamente en busca de insectos y divierte a los visitantes con su comportamiento c\u00f3mico.'}},
  {animalId: 116, da: {name: 'Skestork', desc: 'Skestorken er en elegant vadefugl med et karakteristisk skeformet n\u00e6b og en smuk lyser\u00f8d fjerdragt. Den lever i v\u00e5domr\u00e5der i Amerika og filtrerer sin f\u00f8de gennem vandet. I din zoo vader den graci\u00f8st gennem sit vandbassin og imponerer bes\u00f8gende med sine levende farver.'},
   nl: {name: 'Lepelaar', desc: 'De lepelaar is een elegante waadvogel met een karakteristieke lepelvormige snavel en een prachtig roze verenkleed. Hij leeft in wetlands in Amerika en filtert zijn voedsel door het water. In jouw dierentuin waadt hij sierlijk door zijn waterbassin en maakt indruk op bezoekers met zijn levendige kleuren.'},
   fr: {name: 'Spatule rose', desc: 'La spatule rose est un \u00e9chassier \u00e9l\u00e9gant au bec caract\u00e9ristique en forme de spatule et au magnifique plumage rose. Elle vit dans les zones humides d\'Am\u00e9rique et filtre sa nourriture dans l\'eau. Dans ton zoo, elle patauche gracieusement dans son bassin et impressionne les visiteurs par ses couleurs vives.'},
   es: {name: 'Esp\u00e1tula rosada', desc: 'La esp\u00e1tula rosada es una elegante ave zancuda con un pico caracter\u00edstico en forma de esp\u00e1tula y un hermoso plumaje rosa. Vive en humedales de Am\u00e9rica y filtra su alimento del agua. En tu zoo, vadea con gracia por su estanque y asombra a los visitantes con sus vivos colores.'}},
  {animalId: 117, da: {name: 'Manewolf', desc: 'Manulven er det st\u00f8rste hundedyr i Sydamerika med sine us\u00e6dvanligt lange ben og sin r\u00f8de pels. Den ligner en r\u00e6v p\u00e5 stylter og lever i det brasilianske cerrado. I din zoo patruljerer den elegant gennem sit territorium og tiltr\u00e6kker opm\u00e6rksomhed med sin unikke silhuet.'},
   nl: {name: 'Maneenwolf', desc: 'De manenenwolf is het grootste hondsachtige van Zuid-Amerika met zijn ongewoon lange poten en rode vacht. Hij lijkt op een vos op stelten en leeft in de Braziliaanse cerrado. In jouw dierentuin patrouilleert hij elegant door zijn territorium en trekt de aandacht met zijn unieke silhouet.'},
   fr: {name: 'Loup \u00e0 crini\u00e8re', desc: 'Le loup \u00e0 crini\u00e8re est le plus grand canid\u00e9 d\'Am\u00e9rique du Sud avec ses pattes inhabituellement longues et son pelage roux. Il ressemble \u00e0 un renard sur \u00e9chasses et vit dans le cerrado br\u00e9silien. Dans ton zoo, il patrouille \u00e9l\u00e9gamment dans son territoire et attire l\'attention par sa silhouette unique.'},
   es: {name: 'Lobo de crin', desc: 'El lobo de crin es el c\u00e1nido m\u00e1s grande de Sudam\u00e9rica con sus patas inusualmente largas y su pelaje rojizo. Parece un zorro sobre zancos y vive en el cerrado brasile\u00f1o. En tu zoo, patrulla elegantemente su territorio y atrae la atenci\u00f3n con su silueta \u00fanica.'}},
  {animalId: 118, da: {name: 'Rødkronet trane', desc: 'Den r\u00f8dkronede trane er et symbol p\u00e5 lykke og lang levetid i japansk kultur med sin hvide fjerdragt og r\u00f8de isse. Den kan blive over 150 cm h\u00f8j og udf\u00f8rer smukke parringsdanse. I din zoo danser den elegant og udstr\u00e5ler en majest\u00e6tisk ro, der fascinerer alle bes\u00f8gende.'},
   nl: {name: 'Roodkruinkraanvogel', desc: 'De roodkruinkraanvogel is een symbool van geluk en een lang leven in de Japanse cultuur, met zijn witte verenkleed en rode kruin. Hij kan meer dan 150 cm hoog worden en voert prachtige paringsdansen uit. In jouw dierentuin danst hij elegant en straalt een majestueuze rust uit die alle bezoekers fascineert.'},
   fr: {name: 'Grue du Japon', desc: 'La grue du Japon est un symbole de bonheur et de long\u00e9vit\u00e9 dans la culture japonaise, avec son plumage blanc et sa calotte rouge. Elle peut mesurer plus de 150 cm et ex\u00e9cute de magnifiques danses nuptiales. Dans ton zoo, elle danse avec \u00e9l\u00e9gance et d\u00e9gage une majest\u00e9 sereine qui fascine tous les visiteurs.'},
   es: {name: 'Grulla de Manchuria', desc: 'La grulla de Manchuria es un s\u00edmbolo de felicidad y longevidad en la cultura japonesa, con su plumaje blanco y corona roja. Puede medir m\u00e1s de 150 cm y realiza hermosas danzas nupciales. En tu zoo, baila con elegancia y transmite una majestuosa serenidad que fascina a todos los visitantes.'}},
  {animalId: 119, da: {name: 'Næsebjørn', desc: 'N\u00e6sebj\u00f8rnen er et nysgerrigt og socialt dyr fra Central- og Sydamerika med en lang, bev\u00e6gelig snude. Den bruger sin fleksible n\u00e6se til at s\u00f8ge efter f\u00f8de i jord og blade. I din zoo udforsker den ivrigt hver krog af sin indhegning og morer bes\u00f8gende med sin nysgerrige adf\u00e6rd.'},
   nl: {name: 'Neusbeer', desc: 'De neusbeer is een nieuwsgierig en sociaal dier uit Midden- en Zuid-Amerika met een lange, beweeglijke snuit. Hij gebruikt zijn flexibele neus om in de grond en tussen bladeren naar voedsel te zoeken. In jouw dierentuin verkent hij gretig elke hoek van zijn verblijf en vermaakt bezoekers met zijn nieuwsgierige gedrag.'},
   fr: {name: 'Coati', desc: 'Le coati est un animal curieux et social d\'Am\u00e9rique centrale et du Sud, dot\u00e9 d\'un long museau mobile. Il utilise son nez flexible pour chercher de la nourriture dans le sol et les feuilles. Dans ton zoo, il explore avidement chaque recoin de son enclos et amuse les visiteurs par son comportement curieux.'},
   es: {name: 'Coat\u00ed', desc: 'El coat\u00ed es un animal curioso y social de Am\u00e9rica Central y del Sur con un hocico largo y m\u00f3vil. Usa su nariz flexible para buscar alimento en el suelo y entre las hojas. En tu zoo, explora con entusiasmo cada rinc\u00f3n de su recinto y divierte a los visitantes con su comportamiento curioso.'}},
  {animalId: 120, da: {name: 'Nilgauantilope', desc: 'Nilgauantilopen er den st\u00f8rste asiatiske antilope med en kraftig krop og en karakteristisk bl\u00e5gr\u00e5 pels hos hannerne. Den lever p\u00e5 de indiske sletter og er hellig i hinduismen. I din zoo bev\u00e6ger den sig v\u00e6rdigt gennem sit territorium og imponerer bes\u00f8gende med sin kraftfulde statur.'},
   nl: {name: 'Nijlgau', desc: 'De nijlgau is de grootste Aziatische antilope met een krachtig lichaam en een karakteristieke blauwgrijze vacht bij de mannetjes. Hij leeft op de Indiase vlakten en is heilig in het hindoe\u00efsme. In jouw dierentuin beweegt hij waardig door zijn territorium en maakt indruk op bezoekers met zijn krachtige gestalte.'},
   fr: {name: 'Nilgaut', desc: 'Le nilgaut est la plus grande antilope d\'Asie, au corps puissant et au pelage caract\u00e9ristique bleu-gris chez les m\u00e2les. Il vit dans les plaines indiennes et est sacr\u00e9 dans l\'hindouisme. Dans ton zoo, il se d\u00e9place dignement dans son territoire et impressionne les visiteurs par sa stature imposante.'},
   es: {name: 'Nilgo', desc: 'El nilgo es el ant\u00edlope m\u00e1s grande de Asia, con un cuerpo poderoso y un pelaje caracter\u00edstico gris azulado en los machos. Vive en las llanuras de la India y es sagrado en el hinduismo. En tu zoo, se desplaza con dignidad por su territorio y asombra a los visitantes con su imponente estatura.'}},
  {animalId: 121, da: {name: 'Nilmonitor', desc: 'Nilmonitoren er en af Afrikas st\u00f8rste \u00f8gler og kan blive over 2 meter lang. Den er en fremragende sv\u00f8mmer og lever langs floder og s\u00f8er. I din zoo basker den i solen ved vandkanten og imponerer bes\u00f8gende med sin imponerende st\u00f8rrelse og kraftige hale.'},
   nl: {name: 'Nijlvaraan', desc: 'De nijlvaraan is een van de grootste hagedissen van Afrika en kan meer dan 2 meter lang worden. Hij is een uitstekende zwemmer en leeft langs rivieren en meren. In jouw dierentuin badt hij in de zon bij de waterkant en maakt indruk op bezoekers met zijn indrukwekkende grootte en krachtige staart.'},
   fr: {name: 'Varan du Nil', desc: 'Le varan du Nil est l\'un des plus grands l\u00e9zards d\'Afrique et peut mesurer plus de 2 m\u00e8tres. C\'est un excellent nageur qui vit le long des rivi\u00e8res et des lacs. Dans ton zoo, il se pr\u00e9lasse au soleil au bord de l\'eau et impressionne les visiteurs par sa taille imposante et sa puissante queue.'},
   es: {name: 'Varano del Nilo', desc: 'El varano del Nilo es uno de los lagartos m\u00e1s grandes de \u00c1frica y puede medir m\u00e1s de 2 metros. Es un excelente nadador que vive a lo largo de r\u00edos y lagos. En tu zoo, toma el sol junto al agua y asombra a los visitantes con su impresionante tama\u00f1o y poderosa cola.'}},
  {animalId: 122, da: {name: '\u00d8stlig graseule', desc: 'Den \u00f8stlige graseule er en sj\u00e6lden ugle, der lever i h\u00f8je gr\u00e6sarealer i Australien og Asien. Den har et karakteristisk hjerteformet ansigt og jager sm\u00e5gnagere om natten. I din zoo sidder den stille i sit skjul om dagen og viser sig majest\u00e6tisk ved skumring.'},
   nl: {name: 'Oostelijke grasoul', desc: 'De oostelijke grasoul is een zeldzame uil die leeft in hoge grasgebieden in Australi\u00eb en Azi\u00eb. Hij heeft een karakteristiek hartvormig gezicht en jaagt \'s nachts op kleine knaagdieren. In jouw dierentuin zit hij overdag stil in zijn schuilplaats en laat zich bij schemering majestueus zien.'},
   fr: {name: 'Effraie des herbes', desc: 'L\'effraie des herbes est une chouette rare vivant dans les hautes herbes d\'Australie et d\'Asie. Elle poss\u00e8de un visage caract\u00e9ristique en forme de coeur et chasse les petits rongeurs la nuit. Dans ton zoo, elle reste discr\u00e8te dans son abri le jour et se montre majestueusement au cr\u00e9puscule.'},
   es: {name: 'Lechuza de praderas', desc: 'La lechuza de praderas es un b\u00faho raro que vive en pastizales altos de Australia y Asia. Tiene un rostro caracter\u00edstico en forma de coraz\u00f3n y caza peque\u00f1os roedores por la noche. En tu zoo, se mantiene tranquila en su refugio durante el d\u00eda y se muestra majestuosa al atardecer.'}},
  {animalId: 123, da: {name: 'Pansern\u00e6sehorn', desc: 'Pansern\u00e6sehornet er et imponerende dyr fra Indien med en karakteristisk panserlignet hud, der ligner plader af rustning. Det er det femtest\u00f8rste landdyr og lever i sumpede omr\u00e5der. I din zoo vandrer det majest\u00e6tisk gennem sit territorium og fylder bes\u00f8gende med \u00e6refrygt.'},
   nl: {name: 'Bepantserd neushoorn', desc: 'De bepantserde neushoorn is een imposant dier uit India met een karakteristieke pantserachtige huid die lijkt op platen van een harnas. Het is het vijfde grootste landdier en leeft in moerassige gebieden. In jouw dierentuin wandelt hij majestueus door zijn territorium en vervult bezoekers met ontzag.'},
   fr: {name: 'Rhinoc\u00e9ros indien', desc: 'Le rhinoc\u00e9ros indien est un animal imposant d\'Inde, \u00e0 la peau caract\u00e9ristique ressemblant \u00e0 des plaques d\'armure. C\'est le cinqui\u00e8me plus grand animal terrestre et il vit dans les zones mar\u00e9cageuses. Dans ton zoo, il d\u00e9ambule majestueusement dans son territoire et remplit les visiteurs d\'admiration.'},
   es: {name: 'Rinoceronte indio', desc: 'El rinoceronte indio es un animal imponente de la India con una piel caracter\u00edstica que parece placas de armadura. Es el quinto animal terrestre m\u00e1s grande y vive en zonas pantanosas. En tu zoo, pasea majestuosamente por su territorio y llena de asombro a los visitantes.'}},
  {animalId: 124, da: {name: 'Hest', desc: 'Hesten er menneskets trofaste f\u00f8lgesvend i tusinder af \u00e5r og har spillet en afg\u00f8rende rolle i civilisationens udvikling. Den er kendt for sin styrke, intelligens og sociale natur. I din zoo galopperer den frit p\u00e5 engen og gl\u00e6der bes\u00f8gende med sin elegante bev\u00e6gelse.'},
   nl: {name: 'Paard', desc: 'Het paard is al duizenden jaren de trouwe metgezel van de mens en heeft een cruciale rol gespeeld in de ontwikkeling van de beschaving. Het staat bekend om zijn kracht, intelligentie en sociale aard. In jouw dierentuin galoppeert het vrij over de weide en verblijdt bezoekers met zijn elegante bewegingen.'},
   fr: {name: 'Cheval', desc: 'Le cheval est le fid\u00e8le compagnon de l\'homme depuis des milliers d\'ann\u00e9es et a jou\u00e9 un r\u00f4le crucial dans le d\u00e9veloppement de la civilisation. Il est connu pour sa force, son intelligence et sa nature sociale. Dans ton zoo, il galope librement dans la prairie et r\u00e9jouit les visiteurs par ses mouvements \u00e9l\u00e9gants.'},
   es: {name: 'Caballo', desc: 'El caballo ha sido el fiel compa\u00f1ero del ser humano durante miles de a\u00f1os y ha desempe\u00f1ado un papel crucial en el desarrollo de la civilizaci\u00f3n. Es conocido por su fuerza, inteligencia y naturaleza social. En tu zoo, galopa libremente por la pradera y alegra a los visitantes con sus elegantes movimientos.'}},
  {animalId: 125, da: {name: 'Poitou-\u00e6sel', desc: 'Poitou-\u00e6slet er en sj\u00e6lden \u00e6selrace fra Frankrig med en us\u00e6dvanligt lang og kr\u00f8llet pels, der kan danne lokker. Det er en af de \u00e6ldste og mest truede \u00e6selracer i verden. I din zoo strejfer det roligt rundt og fascinerer bes\u00f8gende med sin enest\u00e5ende manke.'},
   nl: {name: 'Poitou-ezel', desc: 'De Poitou-ezel is een zeldzaam ezelras uit Frankrijk met een ongewoon lange en krullende vacht die dreadlocks kan vormen. Het is een van de oudste en meest bedreigde ezelrassen ter wereld. In jouw dierentuin slentert hij rustig rond en fascineert bezoekers met zijn bijzondere manen.'},
   fr: {name: 'Baudet du Poitou', desc: 'Le baudet du Poitou est une race d\'\u00e2ne rare de France au pelage inhabituellement long et boucl\u00e9 pouvant former des cadenettes. C\'est l\'une des races d\'\u00e2nes les plus anciennes et les plus menac\u00e9es au monde. Dans ton zoo, il se prom\u00e8ne tranquillement et fascine les visiteurs par sa crini\u00e8re extraordinaire.'},
   es: {name: 'Burro de Poitou', desc: 'El burro de Poitou es una raza rara de asno de Francia con un pelaje inusualmente largo y rizado que puede formar rastas. Es una de las razas de asnos m\u00e1s antiguas y amenazadas del mundo. En tu zoo, pasea tranquilamente y fascina a los visitantes con su extraordinaria melena.'}},
  {animalId: 126, da: {name: 'Kæmpekanin', desc: 'K\u00e6mpekaninen er en imponerende kaninrace, der kan veje over 10 kg og blive over 70 cm lang. Trods sin st\u00f8rrelse er den blid og venlig. I din zoo ligger den afslappet i sit indhegning og lader sig gerne kramme af begejstrede bes\u00f8gende.'},
   nl: {name: 'Reusachtig konijn', desc: 'Het reusachtige konijn is een imposant konijnenras dat meer dan 10 kg kan wegen en meer dan 70 cm lang kan worden. Ondanks zijn grootte is het zachtaardig en vriendelijk. In jouw dierentuin ligt het ontspannen in zijn verblijf en laat zich graag knuffelen door enthousiaste bezoekers.'},
   fr: {name: 'Lapin g\u00e9ant', desc: 'Le lapin g\u00e9ant est une race impressionnante pouvant peser plus de 10 kg et mesurer plus de 70 cm. Malgr\u00e9 sa taille, il est doux et amical. Dans ton zoo, il se repose tranquillement dans son enclos et se laisse volontiers c\u00e2liner par les visiteurs enthousiastes.'},
   es: {name: 'Conejo gigante', desc: 'El conejo gigante es una raza impresionante que puede pesar m\u00e1s de 10 kg y medir m\u00e1s de 70 cm. A pesar de su tama\u00f1o, es d\u00f3cil y amigable. En tu zoo, descansa tranquilamente en su recinto y se deja acariciar con gusto por los visitantes entusiasmados.'}},
  {animalId: 127, da: {name: 'Sumpkat', desc: 'Sumpkatten er en vildkat fra Asien og Nordafrika, der trives i v\u00e5domr\u00e5der og sumpede landskaber. Den er en fremragende sv\u00f8mmer og kan endda dykke efter fisk. I din zoo udforsker den sit vandrige habitat og overrasker bes\u00f8gende med sin evne til at fange fisk.'},
   nl: {name: 'Moeraskat', desc: 'De moeraskat is een wilde kat uit Azi\u00eb en Noord-Afrika die gedijt in wetlands en moerassige landschappen. Hij is een uitstekende zwemmer en kan zelfs duiken om vis te vangen. In jouw dierentuin verkent hij zijn waterrijke habitat en verrast bezoekers met zijn vermogen om vis te vangen.'},
   fr: {name: 'Chat des marais', desc: 'Le chat des marais est un f\u00e9lin sauvage d\'Asie et d\'Afrique du Nord qui prosp\u00e8re dans les zones humides et mar\u00e9cageuses. C\'est un excellent nageur capable de plonger pour attraper des poissons. Dans ton zoo, il explore son habitat aquatique et surprend les visiteurs par sa capacit\u00e9 \u00e0 p\u00eacher.'},
   es: {name: 'Gato de la jungla', desc: 'El gato de la jungla es un felino salvaje de Asia y norte de \u00c1frica que prospera en humedales y paisajes pantanosos. Es un excelente nadador capaz de bucear para atrapar peces. En tu zoo, explora su h\u00e1bitat acu\u00e1tico y sorprende a los visitantes con su habilidad para pescar.'}},
  {animalId: 128, da: {name: 'F\u00e5r', desc: 'F\u00e5ret er et af de \u00e6ldste tamme husdyr og har v\u00e6ret holdt af mennesker i over 10.000 \u00e5r for sin uld, m\u00e6lk og k\u00f8d. Det er et socialt flokdyr med en blid karakter. I din zoo gr\u00e6sser det fredeligt og lader sig gerne klappe af bes\u00f8gende b\u00f8rn.'},
   nl: {name: 'Schaap', desc: 'Het schaap is een van de oudste gedomesticeerde huisdieren en wordt al meer dan 10.000 jaar door mensen gehouden voor zijn wol, melk en vlees. Het is een sociaal kuddedier met een zachtaardig karakter. In jouw dierentuin graast het vredig en laat zich graag aaien door jonge bezoekers.'},
   fr: {name: 'Mouton', desc: 'Le mouton est l\'un des plus anciens animaux domestiques, \u00e9lev\u00e9 par l\'homme depuis plus de 10 000 ans pour sa laine, son lait et sa viande. C\'est un animal gr\u00e9gaire au caract\u00e8re doux. Dans ton zoo, il broute paisiblement et se laisse volontiers caresser par les jeunes visiteurs.'},
   es: {name: 'Oveja', desc: 'La oveja es uno de los animales dom\u00e9sticos m\u00e1s antiguos, criada por el ser humano desde hace m\u00e1s de 10.000 a\u00f1os por su lana, leche y carne. Es un animal gregario de car\u00e1cter d\u00f3cil. En tu zoo, pasta tranquilamente y se deja acariciar con gusto por los j\u00f3venes visitantes.'}},
  {animalId: 129, da: {name: 'Alligatorskilpadde', desc: 'Alligatorskilpadden er en af verdens st\u00f8rste ferskvandsskildpadder med et kraftigt k\u00e6beparti og en taggekam p\u00e5 skjoldet. Den lever i nordamerikanske floder og kan veje over 100 kg. I din zoo ligger den t\u00e5lmodigt i vandet og fascinerer bes\u00f8gende med sit forhistoriske udseende.'},
   nl: {name: 'Alligatorschildpad', desc: 'De alligatorschildpad is een van de grootste zoetwaterschilpadden ter wereld met een krachtig kaakgedeelte en een gekartelde kam op het schild. Hij leeft in Noord-Amerikaanse rivieren en kan meer dan 100 kg wegen. In jouw dierentuin ligt hij geduldig in het water en fascineert bezoekers met zijn prehistorische uiterlijk.'},
   fr: {name: 'Tortue alligator', desc: 'La tortue alligator est l\'une des plus grandes tortues d\'eau douce au monde, dot\u00e9e de m\u00e2choires puissantes et d\'une cr\u00eate dentel\u00e9e sur sa carapace. Elle vit dans les rivi\u00e8res d\'Am\u00e9rique du Nord et peut peser plus de 100 kg. Dans ton zoo, elle repose patiemment dans l\'eau et fascine les visiteurs par son allure pr\u00e9historique.'},
   es: {name: 'Tortuga caim\u00e1n', desc: 'La tortuga caim\u00e1n es una de las tortugas de agua dulce m\u00e1s grandes del mundo, con mand\u00edbulas poderosas y una cresta dentada en su caparaz\u00f3n. Vive en r\u00edos de Norteam\u00e9rica y puede pesar m\u00e1s de 100 kg. En tu zoo, reposa pacientemente en el agua y fascina a los visitantes con su aspecto prehist\u00f3rico.'}},
  {animalId: 130, da: {name: 'Skotsk H\u00f8jlandskv\u00e6g', desc: 'Skotsk H\u00f8jlandskv\u00e6g er en gammel kv\u00e6grace fra de skotske h\u00f8jlande med lang, stridt pels og imponerende horn. De er ekstremt modstandsdygtige over for h\u00e5rdt vejr. I din zoo gr\u00e6sser de fredeligt og tiltr\u00e6kker opm\u00e6rksomhed med deres charmerende, h\u00e5rede udseende.'},
   nl: {name: 'Schotse hooglander', desc: 'De Schotse hooglander is een oud runderras uit de Schotse hooglanden met een lange, ruige vacht en imposante horens. Ze zijn extreem bestand tegen slecht weer. In jouw dierentuin grazen ze vredig en trekken de aandacht met hun charmante, harige verschijning.'},
   fr: {name: 'Vache Highland', desc: 'La vache Highland est une ancienne race bovine des Highlands \u00e9cossais, au long pelage hirsute et aux cornes imposantes. Elles sont extr\u00eamement r\u00e9sistantes aux intemp\u00e9ries. Dans ton zoo, elles broutent paisiblement et attirent l\'attention par leur charmante allure poilue.'},
   es: {name: 'Vaca de las Highlands', desc: 'La vaca de las Highlands es una antigua raza bovina de las tierras altas escocesas con un pelaje largo y \u00e1spero y cuernos imponentes. Son extremadamente resistentes al mal tiempo. En tu zoo, pastan tranquilamente y atraen la atenci\u00f3n con su encantador aspecto peludo.'}},
  {animalId: 131, da: {name: 'Skosknæbbet stork', desc: 'Den skoskn\u00e6bbede stork er en af Afrikas mest fascinerende fugle med sit enorme, skoformede n\u00e6b og et gennemtr\u00e6ngende blik. Den lever i sumpomr\u00e5der og kan st\u00e5 ubev\u00e6gelig i timevis p\u00e5 jagt. I din zoo st\u00e5r den majest\u00e6tisk ved vandet og imponerer bes\u00f8gende med sin imponerende statur.'},
   nl: {name: 'Schoenbekooievaar', desc: 'De schoenbekooievaar is een van de meest fascinerende vogels van Afrika met zijn enorme, schoenvormige snavel en doordringende blik. Hij leeft in moerasgebieden en kan urenlang onbeweeglijk staan tijdens de jacht. In jouw dierentuin staat hij majestueus bij het water en maakt indruk op bezoekers met zijn imposante gestalte.'},
   fr: {name: 'Bec-en-sabot', desc: 'Le bec-en-sabot est l\'un des oiseaux les plus fascinants d\'Afrique avec son \u00e9norme bec en forme de sabot et son regard per\u00e7ant. Il vit dans les mar\u00e9cages et peut rester immobile pendant des heures en chassant. Dans ton zoo, il se tient majestueusement au bord de l\'eau et impressionne les visiteurs par sa stature imposante.'},
   es: {name: 'Picozapato', desc: 'El picozapato es una de las aves m\u00e1s fascinantes de \u00c1frica con su enorme pico en forma de zapato y mirada penetrante. Vive en zonas pantanosas y puede permanecer inm\u00f3vil durante horas mientras caza. En tu zoo, se mantiene majestuosamente junto al agua y asombra a los visitantes con su imponente estatura.'}},
  {animalId: 132, da: {name: 'Svane', desc: 'Svanen er et symbol p\u00e5 sk\u00f8nhed og elegance med sin lange hals og hvide fjerdragt. Den lever p\u00e5 s\u00f8er og floder i Europa og er kendt for sine livslange parforhold. I din zoo glider den yndefuldt hen over vandet og skaber en romantisk atmosf\u00e6re i zooen.'},
   nl: {name: 'Zwaan', desc: 'De zwaan is een symbool van schoonheid en elegantie met zijn lange hals en witte verenkleed. Hij leeft op meren en rivieren in Europa en staat bekend om zijn levenslange partnerschap. In jouw dierentuin glijdt hij sierlijk over het water en cre\u00ebert een romantische sfeer in de dierentuin.'},
   fr: {name: 'Cygne', desc: 'Le cygne est un symbole de beaut\u00e9 et d\'\u00e9l\u00e9gance avec son long cou et son plumage blanc. Il vit sur les lacs et rivi\u00e8res d\'Europe et est connu pour ses liens de couple \u00e0 vie. Dans ton zoo, il glisse gracieusement sur l\'eau et cr\u00e9e une atmosph\u00e8re romantique.'},
   es: {name: 'Cisne', desc: 'El cisne es un s\u00edmbolo de belleza y elegancia con su largo cuello y plumaje blanco. Vive en lagos y r\u00edos de Europa y es conocido por sus parejas de por vida. En tu zoo, se desliza con gracia sobre el agua y crea una atm\u00f3sfera rom\u00e1ntica.'}},
  {animalId: 133, da: {name: 'Shetlandspony', desc: 'Shetlandsponyen er en lille men st\u00e6rk hesterace fra Shetlands\u00f8erne i Skotland, der kun bliver omkring 100 cm h\u00f8j. Trods sin lille st\u00f8rrelse er den utrolig st\u00e6rk og modig. I din zoo er den et yndlingsdyr blandt b\u00f8rn og lader sig gerne klappe og fodre.'},
   nl: {name: 'Shetlandpony', desc: 'De Shetlandpony is een klein maar sterk paardenras van de Shetlandeilanden in Schotland, dat slechts ongeveer 100 cm hoog wordt. Ondanks zijn kleine formaat is hij ongelooflijk sterk en moedig. In jouw dierentuin is hij een favoriet bij kinderen en laat zich graag aaien en voeren.'},
   fr: {name: 'Poney Shetland', desc: 'Le poney Shetland est une race \u00e9quine petite mais robuste originaire des \u00eeles Shetland en \u00c9cosse, ne mesurant qu\'environ 100 cm. Malgr\u00e9 sa petite taille, il est incroyablement fort et courageux. Dans ton zoo, c\'est un favori des enfants qui adorent le caresser et le nourrir.'},
   es: {name: 'Poni Shetland', desc: 'El poni Shetland es una raza equina peque\u00f1a pero fuerte de las islas Shetland en Escocia, que solo mide unos 100 cm. A pesar de su peque\u00f1o tama\u00f1o, es incre\u00edblemente fuerte y valiente. En tu zoo, es el favorito de los ni\u00f1os que adoran acariciarlo y alimentarlo.'}},
  {animalId: 134, da: {name: 'Eremitibis', desc: 'Eremitibissen er en kritisk truet fugl med et skallet hoved og en lang, krummet n\u00e6b. Den lever i klippefyldte omr\u00e5der i Marokko og Tyrkiet. I din zoo sidder den p\u00e5 klippefremspring og overrasker bes\u00f8gende med sit us\u00e6dvanlige og fascinerende udseende.'},
   nl: {name: 'Heremietibis', desc: 'De heremietibis is een ernstig bedreigde vogel met een kaal hoofd en een lange, gebogen snavel. Hij leeft in rotsachtige gebieden in Marokko en Turkije. In jouw dierentuin zit hij op rotsrichels en verrast bezoekers met zijn ongewone en fascinerende uiterlijk.'},
   fr: {name: 'Ibis chauve du Nord', desc: 'L\'ibis chauve du Nord est un oiseau en danger critique avec une t\u00eate chauve et un long bec recourb\u00e9. Il vit dans les zones rocheuses du Maroc et de la Turquie. Dans ton zoo, il se perche sur les corniches rocheuses et surprend les visiteurs par son apparence inhabituelle et fascinante.'},
   es: {name: 'Ibis eremita del norte', desc: 'El ibis eremita del norte es un ave en peligro cr\u00edtico con una cabeza calva y un pico largo y curvado. Vive en zonas rocosas de Marruecos y Turqu\u00eda. En tu zoo, se posa en salientes rocosos y sorprende a los visitantes con su inusual y fascinante apariencia.'}},
  {animalId: 135, da: {name: 'Sydafrikansk kronekranefugl', desc: 'Den sydafrikanske kronekranefugl er en elegant fugl med en karakteristisk gylden krone af fjer p\u00e5 hovedet. Den lever i Afrikas savanner og v\u00e5domr\u00e5der. I din zoo danser den med udbredte vinger og begejstrer bes\u00f8gende med sin smukke fjerdragt og yndefulde bev\u00e6gelser.'},
   nl: {name: 'Grijze kroonkraanvogel', desc: 'De grijze kroonkraanvogel is een elegante vogel met een karakteristieke gouden kroon van veren op het hoofd. Hij leeft in de savannen en wetlands van Afrika. In jouw dierentuin danst hij met gespreide vleugels en betovert bezoekers met zijn prachtige verenkleed en sierlijke bewegingen.'},
   fr: {name: 'Grue couronnée grise', desc: 'La grue couronnée grise est un oiseau \u00e9l\u00e9gant avec une caract\u00e9ristique couronne dor\u00e9e de plumes sur la t\u00eate. Elle vit dans les savanes et zones humides d\'Afrique. Dans ton zoo, elle danse les ailes d\u00e9ploy\u00e9es et enchante les visiteurs par son magnifique plumage et ses mouvements gracieux.'},
   es: {name: 'Grulla coronada', desc: 'La grulla coronada es un ave elegante con una caracter\u00edstica corona dorada de plumas en la cabeza. Vive en las sabanas y humedales de \u00c1frica. En tu zoo, baila con las alas extendidas y encanta a los visitantes con su hermoso plumaje y movimientos gr\u00e1ciles.'}},
  {animalId: 136, da: {name: 'Tapir', desc: 'Tapiren er et \u00e6ldgammelt dyr, der har eksisteret i millioner af \u00e5r og ligner en blanding af et svin og en n\u00e6sehorn. Den lever i tropiske skove i Sydamerika og Syd\u00f8stasien. I din zoo bader den gerne i sit vandbassin og fascinerer bes\u00f8gende med sin bev\u00e6gelige snude.'},
   nl: {name: 'Tapir', desc: 'De tapir is een oeroud dier dat al miljoenen jaren bestaat en lijkt op een kruising tussen een varken en een neushoorn. Hij leeft in tropische bossen in Zuid-Amerika en Zuidoost-Azi\u00eb. In jouw dierentuin baadt hij graag in zijn waterbassin en fascineert bezoekers met zijn beweeglijke snuit.'},
   fr: {name: 'Tapir', desc: 'Le tapir est un animal ancien qui existe depuis des millions d\'ann\u00e9es et ressemble \u00e0 un croisement entre un porc et un rhinoc\u00e9ros. Il vit dans les for\u00eats tropicales d\'Am\u00e9rique du Sud et d\'Asie du Sud-Est. Dans ton zoo, il aime se baigner dans son bassin et fascine les visiteurs par son museau mobile.'},
   es: {name: 'Tapir', desc: 'El tapir es un animal antiguo que ha existido durante millones de a\u00f1os y parece un cruce entre un cerdo y un rinoceronte. Vive en bosques tropicales de Sudam\u00e9rica y el Sudeste Asi\u00e1tico. En tu zoo, disfruta ba\u00f1\u00e1ndose en su estanque y fascina a los visitantes con su hocico m\u00f3vil.'}},
  {animalId: 137, da: {name: 'Eremitibis', desc: 'Eremitibissen er en af verdens mest truede fugle med sit karakteristiske skaldede hoved og metalskinnende fjerdragt. Den yngler i kolonier p\u00e5 klippeafsatser. I din zoo viser den sit sociale adf\u00e6rd og interagerer livligt med sine artsf\u00e6ller.'},
   nl: {name: 'Heremietibis (Noord)', desc: 'De heremietibis is een van de meest bedreigde vogels ter wereld met zijn karakteristieke kale hoofd en metaalglanzend verenkleed. Hij broedt in kolonies op rotsrichels. In jouw dierentuin toont hij zijn sociale gedrag en communiceert levendig met zijn soortgenoten.'},
   fr: {name: 'Ibis chauve', desc: 'L\'ibis chauve est l\'un des oiseaux les plus menac\u00e9s au monde avec sa t\u00eate caract\u00e9ristique chauve et son plumage aux reflets m\u00e9talliques. Il niche en colonies sur les corniches rocheuses. Dans ton zoo, il montre son comportement social et interagit activement avec ses cong\u00e9n\u00e8res.'},
   es: {name: 'Ibis calvo', desc: 'El ibis calvo es una de las aves m\u00e1s amenazadas del mundo con su caracter\u00edstica cabeza calva y plumaje de reflejos met\u00e1licos. Anida en colonias sobre salientes rocosos. En tu zoo, muestra su comportamiento social e interact\u00faa activamente con sus cong\u00e9neres.'}},
  {animalId: 138, da: {name: 'Vaskebjørn', desc: 'Vaskebj\u00f8rnen er et intelligent og tilpasningsdygtigt dyr, der er kendt for sin sorte ansigtsmaske og sin vane med at vaske sin mad. Den er nataktiv og har yderst f\u00f8lsomme forpoter. I din zoo udforsker den nysgerrigt sin indhegning og underholder bes\u00f8gende med sine fingerf\u00e6rdige poter.'},
   nl: {name: 'Wasbeer', desc: 'De wasbeer is een intelligent en aanpasbaar dier, bekend om zijn zwarte gezichtsmasker en zijn gewoonte om voedsel te wassen. Hij is nachtactief en heeft extreem gevoelige voorpoten. In jouw dierentuin verkent hij nieuwsgierig zijn verblijf en vermaakt bezoekers met zijn handige poten.'},
   fr: {name: 'Raton laveur', desc: 'Le raton laveur est un animal intelligent et adaptable, connu pour son masque facial noir et son habitude de laver sa nourriture. Il est nocturne et poss\u00e8de des pattes avant extr\u00eamement sensibles. Dans ton zoo, il explore curieusement son enclos et amuse les visiteurs avec ses pattes habiles.'},
   es: {name: 'Mapache', desc: 'El mapache es un animal inteligente y adaptable, conocido por su m\u00e1scara facial negra y su costumbre de lavar su comida. Es nocturno y tiene patas delanteras extremadamente sensibles. En tu zoo, explora con curiosidad su recinto y divierte a los visitantes con sus h\u00e1biles patas.'}},
  {animalId: 139, da: {name: 'Hvid stork', desc: 'Den hvide stork er en ikonisk fugl i Europa, kendt for at bygge sine store reder p\u00e5 tage og skorstene. Den tr\u00e6kker hvert \u00e5r til Afrika og tilbage. I din zoo bygger den sit imponerende rede og klapprer forn\u00f8jet med n\u00e6bbet til bes\u00f8gendes begejstring.'},
   nl: {name: 'Ooievaar', desc: 'De ooievaar is een iconische vogel in Europa, bekend om het bouwen van zijn grote nesten op daken en schoorstenen. Hij trekt elk jaar naar Afrika en terug. In jouw dierentuin bouwt hij zijn imposante nest en klettert tevreden met zijn snavel tot vreugde van de bezoekers.'},
   fr: {name: 'Cigogne blanche', desc: 'La cigogne blanche est un oiseau embl\u00e9matique d\'Europe, connue pour construire ses grands nids sur les toits et les chemin\u00e9es. Elle migre chaque ann\u00e9e vers l\'Afrique et retour. Dans ton zoo, elle construit son nid impressionnant et claqu\u00e8te joyeusement du bec pour le plus grand plaisir des visiteurs.'},
   es: {name: 'Cigüeña blanca', desc: 'La cigüeña blanca es un ave ic\u00f3nica de Europa, conocida por construir sus grandes nidos en tejados y chimeneas. Migra cada a\u00f1o a \u00c1frica y de vuelta. En tu zoo, construye su impresionante nido y casta\u00f1etea alegremente con el pico para deleite de los visitantes.'}},
  {animalId: 140, da: {name: 'Situtunga', desc: 'Situtungaen er en halvakvatisk antilope fra Centralafrika med lange, spreddede klove, der hj\u00e6lper den med at g\u00e5 p\u00e5 sumpet underlag. Hannen har spiralformede horn og en m\u00f8rk pels. I din zoo vader den elegant gennem sit sumpede habitat og viser sine unikke tilpasninger til bes\u00f8gende.'},
   nl: {name: 'Situtunga', desc: 'De situtunga is een semi-aquatische antilope uit Centraal-Afrika met lange, gespreide hoeven die helpen bij het lopen op moerassige ondergrond. Het mannetje heeft spiraalvormige horens en een donkere vacht. In jouw dierentuin waadt hij elegant door zijn moerassige habitat en toont zijn unieke aanpassingen aan bezoekers.'},
   fr: {name: 'Sitatunga', desc: 'Le sitatunga est une antilope semi-aquatique d\'Afrique centrale aux sabots longs et \u00e9cart\u00e9s qui l\'aident \u00e0 marcher sur les sols mar\u00e9cageux. Le m\u00e2le porte des cornes spiral\u00e9es et un pelage sombre. Dans ton zoo, il patauche \u00e9l\u00e9gamment dans son habitat mar\u00e9cageux et montre ses adaptations uniques aux visiteurs.'},
   es: {name: 'Situtunga', desc: 'El situtunga es un ant\u00edlope semiacu\u00e1tico de \u00c1frica Central con pezu\u00f1as largas y separadas que le ayudan a caminar sobre terreno pantanoso. El macho tiene cuernos en espiral y pelaje oscuro. En tu zoo, vadea elegantemente por su h\u00e1bitat pantanoso y muestra sus adaptaciones \u00fanicas a los visitantes.'}},
  // Biome 200
  {animalId: 201, da: {name: 'Langtbenet musvåge', desc: 'Den langtbenede musv\u00e5ge er en stor rovfugl fra Nordafrika og Mellem\u00f8sten med us\u00e6dvanligt lange ben til at jage i \u00e5bne landskaber. Den sv\u00e6ver majest\u00e6tisk over \u00f8rkenen og stepperne. I din zoo sidder den p\u00e5 sin udsigtspost og scanner omgivelserne med sine skarpe \u00f8jne.'},
   nl: {name: 'Langbeenbuizerd', desc: 'De langbeenbuizerd is een grote roofvogel uit Noord-Afrika en het Midden-Oosten met ongewoon lange poten om in open landschappen te jagen. Hij zweeft majestueus boven de woestijn en steppen. In jouw dierentuin zit hij op zijn uitkijkpost en scant de omgeving met zijn scherpe ogen.'},
   fr: {name: 'Buse f\u00e9roce', desc: 'La buse f\u00e9roce est un grand rapace d\'Afrique du Nord et du Moyen-Orient aux pattes inhabituellement longues pour chasser dans les paysages ouverts. Elle plane majestueusement au-dessus du d\u00e9sert et des steppes. Dans ton zoo, elle se perche sur son poste d\'observation et scrute les environs de ses yeux per\u00e7ants.'},
   es: {name: 'Busardo moro', desc: 'El busardo moro es una gran rapaz del norte de \u00c1frica y Oriente Medio con patas inusualmente largas para cazar en paisajes abiertos. Planea majestuosamente sobre el desierto y las estepas. En tu zoo, se posa en su puesto de observaci\u00f3n y escanea el entorno con sus ojos agudos.'}},
  {animalId: 202, da: {name: 'Amerikansk bison', desc: 'Den amerikanske bison er det st\u00f8rste landdyr i Nordamerika og kan veje over 900 kg. Den var engang t\u00e6t p\u00e5 udryddelse, men er nu reddet takket v\u00e6re bevaringsindsatser. I din zoo bev\u00e6ger den sig majest\u00e6tisk gennem sit vidt udstrakte areal og imponerer bes\u00f8gende med sin enorme st\u00f8rrelse.'},
   nl: {name: 'Amerikaanse bizon', desc: 'De Amerikaanse bizon is het grootste landdier van Noord-Amerika en kan meer dan 900 kg wegen. Hij was ooit bijna uitgestorven, maar is nu gered dankzij beschermingsmaatregelen. In jouw dierentuin beweegt hij zich majestueus door zijn uitgestrekte terrein en maakt indruk op bezoekers met zijn enorme omvang.'},
   fr: {name: 'Bison am\u00e9ricain', desc: 'Le bison am\u00e9ricain est le plus grand animal terrestre d\'Am\u00e9rique du Nord et peut peser plus de 900 kg. Il a \u00e9t\u00e9 proche de l\'extinction mais a \u00e9t\u00e9 sauv\u00e9 gr\u00e2ce aux efforts de conservation. Dans ton zoo, il se d\u00e9place majestueusement dans son vaste enclos et impressionne les visiteurs par son \u00e9norme taille.'},
   es: {name: 'Bisonte americano', desc: 'El bisonte americano es el animal terrestre m\u00e1s grande de Norteam\u00e9rica y puede pesar m\u00e1s de 900 kg. Estuvo cerca de la extinci\u00f3n, pero fue salvado gracias a esfuerzos de conservaci\u00f3n. En tu zoo, se desplaza majestuosamente por su amplio recinto y asombra a los visitantes con su enorme tama\u00f1o.'}},
  {animalId: 203, da: {name: 'Andesr\u00e6v', desc: 'Andesr\u00e6ven er en lille, elegant r\u00e6v fra det sydamerikanske h\u00f8jland med en tyk pels i gr\u00e5 og brune nuancer. Den lever i h\u00f8jtliggende bjergomr\u00e5der og er tilpasset det kolde klima. I din zoo strejfer den rundt i sit bjerglandskab og charmer bes\u00f8gende med sin bl\u00f8de pels.'},
   nl: {name: 'Andenvos', desc: 'De Andenvos is een kleine, elegante vos uit het Zuid-Amerikaanse hoogland met een dikke vacht in grijze en bruine tinten. Hij leeft in hooggelegen berggebieden en is aangepast aan het koude klimaat. In jouw dierentuin zwerft hij door zijn berglandschap en betovert bezoekers met zijn zachte vacht.'},
   fr: {name: 'Renard des Andes', desc: 'Le renard des Andes est un petit renard \u00e9l\u00e9gant des hauts plateaux sud-am\u00e9ricains au pelage \u00e9pais aux nuances grises et brunes. Il vit en haute altitude et est adapt\u00e9 au climat froid. Dans ton zoo, il arpente son paysage montagneux et charme les visiteurs par sa fourrure douce.'},
   es: {name: 'Zorro andino', desc: 'El zorro andino es un peque\u00f1o y elegante zorro de las tierras altas sudamericanas con un pelaje espeso en tonos grises y marrones. Vive en zonas monta\u00f1osas de gran altitud y est\u00e1 adaptado al clima fr\u00edo. En tu zoo, recorre su paisaje monta\u00f1oso y encanta a los visitantes con su suave pelaje.'}},
  {animalId: 204, da: {name: 'Angoraged', desc: 'Angorageden er en gedeart, der er ber\u00f8mt for sin ekstremt bl\u00f8de og lette mohairuld. Den stammer oprindeligt fra Ankara-regionen i Tyrkiet. I din zoo klatrer den nysgerrigt p\u00e5 klipper og charmer bes\u00f8gende med sin bl\u00f8de, b\u00f8lgende pels.'},
   nl: {name: 'Angorager', desc: 'De angorageit is een geitenras dat beroemd is om zijn extreem zachte en lichte mohairdwol. Het stamt oorspronkelijk uit de regio Ankara in Turkije. In jouw dierentuin klimt hij nieuwsgierig op rotsen en betovert bezoekers met zijn zachte, golvende vacht.'},
   fr: {name: 'Ch\u00e8vre angora', desc: 'La ch\u00e8vre angora est une race caprine c\u00e9l\u00e8bre pour sa laine mohair extr\u00eamement douce et l\u00e9g\u00e8re. Elle est originaire de la r\u00e9gion d\'Ankara en Turquie. Dans ton zoo, elle grimpe curieusement sur les rochers et charme les visiteurs par sa toison douce et ondul\u00e9e.'},
   es: {name: 'Cabra angora', desc: 'La cabra angora es una raza caprina famosa por su lana mohair extremadamente suave y ligera. Es originaria de la regi\u00f3n de Ankara en Turqu\u00eda. En tu zoo, trepa con curiosidad por las rocas y encanta a los visitantes con su suave y ondulado pelaje.'}},
  {animalId: 205, da: {name: 'Bongo', desc: 'Bongoen er en stor skovantilope fra Afrika med en r\u00f8dlig-brun pels og hvide striber. Den er en af de st\u00f8rste og mest farverige antilopearter. I din zoo strejfer den gennem sin skovrige indhegning og imponerer bes\u00f8gende med sit smukke stribem\u00f8nster.'},
   nl: {name: 'Bongo', desc: 'De bongo is een grote bosantilope uit Afrika met een roodbruine vacht en witte strepen. Het is een van de grootste en meest kleurrijke antilopesoorten. In jouw dierentuin zwerft hij door zijn bosrijke verblijf en maakt indruk op bezoekers met zijn prachtige streeppatroon.'},
   fr: {name: 'Bongo', desc: 'Le bongo est une grande antilope foresti\u00e8re d\'Afrique au pelage brun-roux ray\u00e9 de blanc. C\'est l\'une des plus grandes et des plus color\u00e9es des antilopes. Dans ton zoo, il se prom\u00e8ne dans son enclos bois\u00e9 et impressionne les visiteurs par son magnifique motif ray\u00e9.'},
   es: {name: 'Bongo', desc: 'El bongo es un gran ant\u00edlope de bosque africano con un pelaje marr\u00f3n rojizo y rayas blancas. Es una de las especies de ant\u00edlopes m\u00e1s grandes y coloridas. En tu zoo, deambula por su recinto boscoso y asombra a los visitantes con su hermoso patr\u00f3n de rayas.'}},
  {animalId: 206, da: {name: 'Flodsvin', desc: 'Flodsvinet er verdens st\u00f8rste gnaver og kan veje op til 65 kg. Det lever i grupper n\u00e6r vandl\u00f8b i Sydamerika og er en fremragende sv\u00f8mmer. I din zoo sv\u00f8mmer det glad i sit bassin og hviler i solen, mens bes\u00f8gende beundrer dets afslappede livsstil.'},
   nl: {name: 'Capibara', desc: 'De capibara is het grootste knaagdier ter wereld en kan tot 65 kg wegen. Hij leeft in groepen bij waterlopen in Zuid-Amerika en is een uitstekende zwemmer. In jouw dierentuin zwemt hij vrolijk in zijn bassin en rust in de zon terwijl bezoekers zijn ontspannen levensstijl bewonderen.'},
   fr: {name: 'Capybara', desc: 'Le capybara est le plus grand rongeur du monde et peut peser jusqu\'\u00e0 65 kg. Il vit en groupes pr\u00e8s des cours d\'eau en Am\u00e9rique du Sud et est un excellent nageur. Dans ton zoo, il nage joyeusement dans son bassin et se repose au soleil tandis que les visiteurs admirent son mode de vie d\u00e9contract\u00e9.'},
   es: {name: 'Capibara', desc: 'El capibara es el roedor m\u00e1s grande del mundo y puede pesar hasta 65 kg. Vive en grupos cerca de cursos de agua en Sudam\u00e9rica y es un excelente nadador. En tu zoo, nada alegremente en su estanque y descansa al sol mientras los visitantes admiran su estilo de vida relajado.'}},
  {animalId: 207, da: {name: 'Dikdik', desc: 'Dikdiken er en af Afrikas mindste antilopearter og vejer kun omkring 5 kg. Den har store, udtryksfulde \u00f8jne og en bev\u00e6gelig snude. I din zoo tripper den forsigtigt gennem vegetationen og henrykker bes\u00f8gende med sin diminutive st\u00f8rrelse og ynde.'},
   nl: {name: 'Dikdik', desc: 'De dikdik is een van de kleinste antilopesoorten van Afrika en weegt slechts ongeveer 5 kg. Hij heeft grote, expressieve ogen en een beweeglijke snuit. In jouw dierentuin trippelt hij voorzichtig door de vegetatie en bekoort bezoekers met zijn minuscule formaat en gratie.'},
   fr: {name: 'Dik-dik', desc: 'Le dik-dik est l\'une des plus petites antilopes d\'Afrique et ne p\u00e8se qu\'environ 5 kg. Il a de grands yeux expressifs et un museau mobile. Dans ton zoo, il trottine prudemment \u00e0 travers la v\u00e9g\u00e9tation et enchante les visiteurs par sa taille minuscule et sa gr\u00e2ce.'},
   es: {name: 'Dik-dik', desc: 'El dik-dik es uno de los ant\u00edlopes m\u00e1s peque\u00f1os de \u00c1frica y pesa solo unos 5 kg. Tiene grandes ojos expresivos y un hocico m\u00f3vil. En tu zoo, camina con cautela entre la vegetaci\u00f3n y encanta a los visitantes con su diminuto tama\u00f1o y gracia.'}},
  {animalId: 208, da: {name: 'Emu', desc: 'Emuen er verdens n\u00e6stst\u00f8rste fugl efter strudsen og kan blive op til 190 cm h\u00f8j. Den lever i Australiens \u00e5bne landskaber og kan l\u00f8be med hastigheder op til 50 km/t. I din zoo l\u00f8ber den energisk rundt i sin indhegning og imponerer bes\u00f8gende med sin imponerende h\u00f8jde.'},
   nl: {name: 'Emoe', desc: 'De emoe is de op \u00e9\u00e9n na grootste vogel ter wereld na de struisvogel en kan tot 190 cm hoog worden. Hij leeft in de open landschappen van Australi\u00eb en kan snelheden tot 50 km/u bereiken. In jouw dierentuin rent hij energiek door zijn verblijf en maakt indruk op bezoekers met zijn imposante hoogte.'},
   fr: {name: '\u00c9meu', desc: 'L\'\u00e9meu est le deuxi\u00e8me plus grand oiseau du monde apr\u00e8s l\'autruche et peut mesurer jusqu\'\u00e0 190 cm. Il vit dans les paysages ouverts d\'Australie et peut courir \u00e0 des vitesses allant jusqu\'\u00e0 50 km/h. Dans ton zoo, il court \u00e9nergiquement dans son enclos et impressionne les visiteurs par sa taille imposante.'},
   es: {name: 'Em\u00fa', desc: 'El em\u00fa es la segunda ave m\u00e1s grande del mundo despu\u00e9s del avestruz y puede medir hasta 190 cm. Vive en los paisajes abiertos de Australia y puede correr a velocidades de hasta 50 km/h. En tu zoo, corre en\u00e9rgicamente por su recinto y asombra a los visitantes con su imponente altura.'}},
  {animalId: 209, da: {name: 'Jordulv', desc: 'Jordulven er et us\u00e6dvanligt medlem af hy\u00e6nefamilien, der udelukkende spiser termitter. Den har en stribet pels og en manke, der rejser sig, n\u00e5r den f\u00f8ler sig truet. I din zoo graver den energisk efter insekter og overrasker bes\u00f8gende med sin uventede kost.'},
   nl: {name: 'Aardwolf', desc: 'De aardwolf is een ongewoon lid van de hyenafamilie dat uitsluitend termieten eet. Hij heeft een gestreepte vacht en een manen die overeind gaan staan wanneer hij zich bedreigd voelt. In jouw dierentuin graaft hij energiek naar insecten en verrast bezoekers met zijn onverwachte dieet.'},
   fr: {name: 'Prot\u00e8le', desc: 'Le prot\u00e8le est un membre inhabituel de la famille des hy\u00e8nes qui se nourrit exclusivement de termites. Il poss\u00e8de un pelage ray\u00e9 et une crini\u00e8re qui se dresse lorsqu\'il se sent menac\u00e9. Dans ton zoo, il creuse \u00e9nergiquement \u00e0 la recherche d\'insectes et surprend les visiteurs par son r\u00e9gime alimentaire inattendu.'},
   es: {name: 'Protelo', desc: 'El protelo es un miembro inusual de la familia de las hienas que se alimenta exclusivamente de termitas. Tiene un pelaje rayado y una melena que se eriza cuando se siente amenazado. En tu zoo, excava en\u00e9rgicamente en busca de insectos y sorprende a los visitantes con su inesperada dieta.'}},
  {animalId: 210, da: {name: 'Svinestinkdyr', desc: 'Svinestinkdyret er et lille rovdyr fra Nordamerika med en karakteristisk hvid stribe og en griseagtig snude. Det bruger sin stinkende spray som forsvar mod rovdyr. I din zoo roder det nysgerrigt i sin indhegning og fascinerer bes\u00f8gende med sit sjove udseende.'},
   nl: {name: 'Varkensstreepskunk', desc: 'De varkensstreepskunk is een klein roofdier uit Noord-Amerika met een karakteristieke witte streep en een varkensachtige snuit. Hij gebruikt zijn stinkende spray als verdediging tegen roofdieren. In jouw dierentuin snuffelt hij nieuwsgierig rond in zijn verblijf en fascineert bezoekers met zijn grappige uiterlijk.'},
   fr: {name: 'Mouffette \u00e0 museau de porc', desc: 'La mouffette \u00e0 museau de porc est un petit pr\u00e9dateur d\'Am\u00e9rique du Nord avec une bande blanche caract\u00e9ristique et un museau porcin. Elle utilise son spray malodorant comme d\u00e9fense contre les pr\u00e9dateurs. Dans ton zoo, elle fouine curieusement dans son enclos et fascine les visiteurs par son allure amusante.'},
   es: {name: 'Mofeta de hocico de cerdo', desc: 'La mofeta de hocico de cerdo es un peque\u00f1o depredador de Norteam\u00e9rica con una franja blanca caracter\u00edstica y un hocico porcino. Usa su spray maloliente como defensa contra depredadores. En tu zoo, husmea con curiosidad por su recinto y fascina a los visitantes con su graciosa apariencia.'}},
  {animalId: 211, da: {name: 'Flamingo', desc: 'Flamingoen er en af naturens mest ikoniske fugle med sin smukke lyser\u00f8de fjerdragt og sine lange ben. Den f\u00e5r sin farve fra de krebsdyr, den spiser. I din zoo st\u00e5r den elegant p\u00e5 \u00e9t ben i sit bassin og skaber et farverigt og eksotisk syn for bes\u00f8gende.'},
   nl: {name: 'Flamingo', desc: 'De flamingo is een van de meest iconische vogels in de natuur met zijn prachtige roze verenkleed en lange poten. Hij krijgt zijn kleur van de schaaldieren die hij eet. In jouw dierentuin staat hij elegant op \u00e9\u00e9n poot in zijn bassin en cre\u00ebert een kleurrijk en exotisch tafereel voor bezoekers.'},
   fr: {name: 'Flamant rose', desc: 'Le flamant rose est l\'un des oiseaux les plus embl\u00e9matiques de la nature avec son magnifique plumage rose et ses longues pattes. Il doit sa couleur aux crustac\u00e9s qu\'il consomme. Dans ton zoo, il se tient \u00e9l\u00e9gamment sur une patte dans son bassin et offre un spectacle color\u00e9 et exotique aux visiteurs.'},
   es: {name: 'Flamenco', desc: 'El flamenco es una de las aves m\u00e1s ic\u00f3nicas de la naturaleza con su hermoso plumaje rosa y largas patas. Obtiene su color de los crust\u00e1ceos que come. En tu zoo, se mantiene elegantemente sobre una pata en su estanque y ofrece un espect\u00e1culo colorido y ex\u00f3tico a los visitantes.'}},
  {animalId: 212, da: {name: 'Gaffelantilope', desc: 'Gaffelantilopen er det hurtigste landdyr i Nordamerika og kan n\u00e5 hastigheder op til 88 km/t. Den har karakteristiske gaffelformede horn og lever p\u00e5 de \u00e5bne pr\u00e6rier. I din zoo l\u00f8ber den med imponerende fart over sit udstrakte areal og begejstrer bes\u00f8gende med sin atletiske form\u00e5en.'},
   nl: {name: 'Pronghorn', desc: 'De pronghorn is het snelste landdier van Noord-Amerika en kan snelheden tot 88 km/u bereiken. Hij heeft karakteristieke vorkvormige horens en leeft op de open prairies. In jouw dierentuin rent hij met indrukwekkende snelheid over zijn uitgestrekte terrein en begeistert bezoekers met zijn atletische prestaties.'},
   fr: {name: 'Antilocapre', desc: 'L\'antilocapre est l\'animal terrestre le plus rapide d\'Am\u00e9rique du Nord, capable d\'atteindre 88 km/h. Elle poss\u00e8de des cornes caract\u00e9ristiques en forme de fourche et vit dans les prairies ouvertes. Dans ton zoo, elle court \u00e0 une vitesse impressionnante dans son vaste enclos et enthousiasme les visiteurs par ses prouesses athl\u00e9tiques.'},
   es: {name: 'Berrendo', desc: 'El berrendo es el animal terrestre m\u00e1s r\u00e1pido de Norteam\u00e9rica, capaz de alcanzar los 88 km/h. Tiene cuernos caracter\u00edsticos en forma de horquilla y vive en las praderas abiertas. En tu zoo, corre a una velocidad impresionante por su amplio recinto y entusiasma a los visitantes con sus proezas atl\u00e9ticas.'}},
  {animalId: 213, da: {name: 'Gepard', desc: 'Geparden er verdens hurtigste landdyr og kan n\u00e5 hastigheder op til 120 km/t p\u00e5 f\u00e5 sekunder. Den har en slank krop, lange ben og karakteristiske sorte t\u00e5restriber. I din zoo sprinter den elegant over savannearealet og efterlader bes\u00f8gende m\u00e5ll\u00f8se af beundring.'},
   nl: {name: 'Jachtluipaard', desc: 'De jachtluipaard is het snelste landdier ter wereld en kan in enkele seconden snelheden tot 120 km/u bereiken. Hij heeft een slank lichaam, lange poten en karakteristieke zwarte traanstrepen. In jouw dierentuin sprint hij elegant over het savanneterrein en laat bezoekers sprakeloos van bewondering achter.'},
   fr: {name: 'Gu\u00e9pard', desc: 'Le gu\u00e9pard est l\'animal terrestre le plus rapide du monde, capable d\'atteindre 120 km/h en quelques secondes. Il a un corps \u00e9lanc\u00e9, de longues pattes et des lignes noires caract\u00e9ristiques sous les yeux. Dans ton zoo, il sprinte \u00e9l\u00e9gamment dans la savane et laisse les visiteurs bouche b\u00e9e d\'admiration.'},
   es: {name: 'Guepardo', desc: 'El guepardo es el animal terrestre m\u00e1s r\u00e1pido del mundo, capaz de alcanzar 120 km/h en pocos segundos. Tiene un cuerpo esbelto, patas largas y caracter\u00edsticas l\u00edneas negras bajo los ojos. En tu zoo, sprinta elegantemente por la sabana y deja a los visitantes boquiabiertos de admiraci\u00f3n.'}},
  {animalId: 214, da: {name: 'Guldfasan', desc: 'Guldfasanen er en af verdens mest farvestr\u00e5lende fugle med sin gyldne nakkefjerbusk og sine r\u00f8de og bl\u00e5 fjer. Den stammer fra Kinas bjergskove. I din zoo spankulerer hannen stolt og viser sin pr\u00e6gtige fjerdragt frem i en spektakul\u00e6r parringsdans.'},
   nl: {name: 'Goudfazant', desc: 'De goudfazant is een van de meest kleurrijke vogels ter wereld met zijn gouden nakkuif en rode en blauwe veren. Hij stamt uit de bergbossen van China. In jouw dierentuin paradeert het mannetje trots en toont zijn prachtige verenkleed in een spectaculaire paringsdans.'},
   fr: {name: 'Faisan dor\u00e9', desc: 'Le faisan dor\u00e9 est l\'un des oiseaux les plus color\u00e9s au monde avec sa huppe dor\u00e9e et ses plumes rouges et bleues. Il est originaire des for\u00eats montagneuses de Chine. Dans ton zoo, le m\u00e2le parade fi\u00e8rement et exhibe son magnifique plumage dans une danse nuptiale spectaculaire.'},
   es: {name: 'Fais\u00e1n dorado', desc: 'El fais\u00e1n dorado es una de las aves m\u00e1s coloridas del mundo con su cresta dorada y plumas rojas y azules. Es originario de los bosques monta\u00f1osos de China. En tu zoo, el macho se pavonea orgullosamente y exhibe su magn\u00edfico plumaje en una espectacular danza nupcial.'}},
  {animalId: 215, da: {name: 'Grevys zebra', desc: 'Grevys zebra er den st\u00f8rste af alle zebraarter med tynde, t\u00e6tte striber og store, runde \u00f8rer. Den lever i de t\u00f8rre steppe- og halv\u00f8rkenomr\u00e5der i \u00d8stafrika. I din zoo galopperer den elegant over savannen og imponerer bes\u00f8gende med sit unikke stribem\u00f8nster.'},
   nl: {name: 'Gr\u00e9vy-zebra', desc: 'De Gr\u00e9vy-zebra is de grootste van alle zebrasoorten met dunne, dichte strepen en grote, ronde oren. Hij leeft in de droge steppe- en halfwoestijngebieden van Oost-Afrika. In jouw dierentuin galoppeert hij elegant over de savanne en maakt indruk op bezoekers met zijn unieke streeppatroon.'},
   fr: {name: 'Z\u00e8bre de Gr\u00e9vy', desc: 'Le z\u00e8bre de Gr\u00e9vy est le plus grand de tous les z\u00e8bres avec des rayures fines et serr\u00e9es et de grandes oreilles rondes. Il vit dans les steppes arides et semi-d\u00e9sertiques d\'Afrique de l\'Est. Dans ton zoo, il galope \u00e9l\u00e9gamment dans la savane et impressionne les visiteurs par son motif de rayures unique.'},
   es: {name: 'Cebra de Gr\u00e9vy', desc: 'La cebra de Gr\u00e9vy es la m\u00e1s grande de todas las especies de cebras con rayas finas y densas y grandes orejas redondas. Vive en las estepas \u00e1ridas y semi\u00e1ridas de \u00c1frica Oriental. En tu zoo, galopa elegantemente por la sabana y asombra a los visitantes con su patr\u00f3n de rayas \u00fanico.'}},
  {animalId: 216, da: {name: 'B\u00e6ltedyr', desc: 'B\u00e6ltedyret er et unikt pattedyr med et h\u00e5rdt, pladed\u00e6kket panser, der beskytter det mod rovdyr. Det lever i Syd- og Nordamerika og graver gange i jorden. I din zoo graver det ivrigt i jorden og ruller sig sammen til en kugle, n\u00e5r det overraskes.'},
   nl: {name: 'Gordeldier', desc: 'Het gordeldier is een uniek zoogdier met een hard, plaatbedekt pantser dat het beschermt tegen roofdieren. Het leeft in Zuid- en Noord-Amerika en graaft tunnels in de grond. In jouw dierentuin graaft hij ijverig in de grond en rolt zich tot een bal wanneer hij verrast wordt.'},
   fr: {name: 'Tatou', desc: 'Le tatou est un mammif\u00e8re unique dot\u00e9 d\'une carapace dure compos\u00e9e de plaques qui le prot\u00e8ge des pr\u00e9dateurs. Il vit en Am\u00e9rique du Sud et du Nord et creuse des galeries dans le sol. Dans ton zoo, il creuse activement dans la terre et se roule en boule lorsqu\'il est surpris.'},
   es: {name: 'Armadillo', desc: 'El armadillo es un mam\u00edfero \u00fanico con una coraza dura compuesta de placas que lo protege de los depredadores. Vive en Am\u00e9rica del Sur y del Norte y excava t\u00faneles en el suelo. En tu zoo, excava activamente en la tierra y se enrolla en una bola cuando se sorprende.'}},
  {animalId: 217, da: {name: 'Halsb\u00e5ndpekari', desc: 'Halsb\u00e5ndpekarien er et svineagtigt dyr fra Amerika med et karakteristisk hvidt halsb\u00e5nd og en st\u00e6rk moskuslugt. Den lever i flokke og er yderst social. I din zoo grynter den tilfredst, mens den roder i jorden efter f\u00f8de, og bes\u00f8gende beundrer dens sociale adf\u00e6rd.'},
   nl: {name: 'Halsbandpekari', desc: 'De halsbandpekari is een varkensachtig dier uit Amerika met een karakteristieke witte halsband en een sterke muskusgeur. Hij leeft in groepen en is zeer sociaal. In jouw dierentuin knort hij tevreden terwijl hij in de grond naar voedsel wroet, en bezoekers bewonderen zijn sociale gedrag.'},
   fr: {name: 'P\u00e9cari \u00e0 collier', desc: 'Le p\u00e9cari \u00e0 collier est un animal d\'allure porcine d\'Am\u00e9rique avec un collier blanc caract\u00e9ristique et une forte odeur musqu\u00e9e. Il vit en troupeaux et est extr\u00eamement social. Dans ton zoo, il grogne de satisfaction en fouillant le sol \u00e0 la recherche de nourriture, et les visiteurs admirent son comportement social.'},
   es: {name: 'Pecar\u00ed de collar', desc: 'El pecar\u00ed de collar es un animal de aspecto porcino de Am\u00e9rica con un collar blanco caracter\u00edstico y un fuerte olor a almizcle. Vive en manadas y es extremadamente social. En tu zoo, gru\u00f1e satisfecho mientras hurga en el suelo buscando alimento, y los visitantes admiran su comportamiento social.'}},
  {animalId: 218, da: {name: 'Sort hjort', desc: 'Den sorte hjort er en elegant antilope fra Indien med en smuk m\u00f8rk pels hos hannerne og spiralformede horn. Den er et af de hurtigste dyr i Asien. I din zoo springer den graci\u00f8st over sletten og f\u00e6ngsler bes\u00f8gende med sin hurtighed og elegance.'},
   nl: {name: 'Zwarte bok', desc: 'De zwarte bok is een elegante antilope uit India met een prachtige donkere vacht bij de mannetjes en spiraalvormige horens. Het is een van de snelste dieren in Azi\u00eb. In jouw dierentuin springt hij sierlijk over de vlakte en boeit bezoekers met zijn snelheid en elegantie.'},
   fr: {name: 'Antilope cervicapre', desc: 'L\'antilope cervicapre est une \u00e9l\u00e9gante antilope d\'Inde au pelage sombre chez les m\u00e2les et aux cornes spiral\u00e9es. C\'est l\'un des animaux les plus rapides d\'Asie. Dans ton zoo, elle bondit gracieusement dans la plaine et captive les visiteurs par sa rapidit\u00e9 et son \u00e9l\u00e9gance.'},
   es: {name: 'Ant\u00edlope negro', desc: 'El ant\u00edlope negro es una elegante especie de la India con un hermoso pelaje oscuro en los machos y cuernos en espiral. Es uno de los animales m\u00e1s r\u00e1pidos de Asia. En tu zoo, salta con gracia por la llanura y cautiva a los visitantes con su velocidad y elegancia.'}},
  {animalId: 219, da: {name: 'Karakal', desc: 'Karakalen er en mellemstor vildkat fra Afrika og Asien med karakteristiske sorte \u00f8retoppe. Den er en fantastisk springer og kan fange fugle i luften med et enkelt spring. I din zoo viser den sin utrolige springevne og begejstrer bes\u00f8gende med sin atletiske elegance.'},
   nl: {name: 'Caracal', desc: 'De caracal is een middelgrote wilde kat uit Afrika en Azi\u00eb met karakteristieke zwarte oorpluimen. Hij is een fantastische springer en kan vogels uit de lucht vangen met een enkele sprong. In jouw dierentuin toont hij zijn ongelooflijke springvermogen en begeistert bezoekers met zijn atletische elegantie.'},
   fr: {name: 'Caracal', desc: 'Le caracal est un f\u00e9lin de taille moyenne d\'Afrique et d\'Asie aux pinceaux noirs caract\u00e9ristiques sur les oreilles. C\'est un sauteur fantastique capable d\'attraper des oiseaux en vol d\'un seul bond. Dans ton zoo, il d\u00e9montre son incroyable capacit\u00e9 de saut et enthousiasme les visiteurs par son \u00e9l\u00e9gance athl\u00e9tique.'},
   es: {name: 'Caracal', desc: 'El caracal es un felino de tama\u00f1o mediano de \u00c1frica y Asia con caracter\u00edsticos penachos negros en las orejas. Es un saltador fant\u00e1stico capaz de atrapar aves en vuelo con un solo salto. En tu zoo, demuestra su incre\u00edble capacidad de salto y entusiasma a los visitantes con su elegancia atl\u00e9tica.'}},
  {animalId: 220, da: {name: 'Ringhaledyr', desc: 'Ringhaledyret er et lille, smidigt rovdyr fra Syd\u00f8stasien med en lang, ringet hale og en slank krop. Det lever i tr\u00e6kronerne og jager insekter og sm\u00e5pattedyr. I din zoo klatrer det beh\u00e6ndigt i grenene og fascinerer bes\u00f8gende med sine akrobatiske kunster.'},
   nl: {name: 'Ringstaartkat', desc: 'De ringstaartkat is een klein, lenig roofdier uit Zuidoost-Azi\u00eb met een lange, geringde staart en een slank lichaam. Hij leeft in boomkruinen en jaagt op insecten en kleine zoogdieren. In jouw dierentuin klimt hij behendig in de takken en fascineert bezoekers met zijn acrobatische kunsten.'},
   fr: {name: 'Linsang', desc: 'Le linsang est un petit pr\u00e9dateur agile d\'Asie du Sud-Est \u00e0 la longue queue annel\u00e9e et au corps \u00e9lanc\u00e9. Il vit dans la canop\u00e9e et chasse insectes et petits mammif\u00e8res. Dans ton zoo, il grimpe habilement dans les branches et fascine les visiteurs par ses acrobaties.'},
   es: {name: 'Linsang', desc: 'El linsang es un peque\u00f1o depredador \u00e1gil del sudeste asi\u00e1tico con una larga cola anillada y un cuerpo esbelto. Vive en las copas de los \u00e1rboles y caza insectos y peque\u00f1os mam\u00edferos. En tu zoo, trepa con destreza por las ramas y fascina a los visitantes con sus acrobacias.'}},
  {animalId: 221, da: {name: 'Lama', desc: 'Lamaen er et venligt og socialt dyr fra Andesbjergene i Sydamerika, der har v\u00e6ret brugt som lastdyr i tusinder af \u00e5r. Den er kendt for sin bl\u00f8de uld og sit venlige v\u00e6sen. I din zoo vandrer den roligt rundt og lader sig gerne fodre og klappe af bes\u00f8gende.'},
   nl: {name: 'Lama', desc: 'De lama is een vriendelijk en sociaal dier uit de Andes in Zuid-Amerika dat al duizenden jaren als lastdier wordt gebruikt. Hij staat bekend om zijn zachte wol en zijn vriendelijke karakter. In jouw dierentuin wandelt hij rustig rond en laat zich graag voeren en aaien door bezoekers.'},
   fr: {name: 'Lama', desc: 'Le lama est un animal amical et social des Andes en Am\u00e9rique du Sud, utilis\u00e9 comme b\u00eate de somme depuis des milliers d\'ann\u00e9es. Il est connu pour sa laine douce et son caract\u00e8re aimable. Dans ton zoo, il se prom\u00e8ne calmement et se laisse volontiers nourrir et caresser par les visiteurs.'},
   es: {name: 'Llama', desc: 'La llama es un animal amigable y social de los Andes sudamericanos, utilizada como animal de carga durante miles de a\u00f1os. Es conocida por su suave lana y su car\u00e1cter amable. En tu zoo, pasea tranquilamente y se deja alimentar y acariciar con gusto por los visitantes.'}},
  {animalId: 222, da: {name: 'Masai-giraf', desc: 'Masai-giraffen er den h\u00f8jeste af alle girafunderarter med et unikt, uregulm\u00e6ssigt pletm\u00f8nster. Den lever i \u00d8stafrikas savanner og kan blive over 5 meter h\u00f8j. I din zoo r\u00e6kker den sit lange hals op mod tr\u00e6kronerne og tilbyder bes\u00f8gende et uforligneligt syn.'},
   nl: {name: 'Masaigiraffe', desc: 'De masaigiraffe is de hoogste van alle girafondersoorten met een uniek, onregelmatig vlekkenpatroon. Hij leeft in de savannen van Oost-Afrika en kan meer dan 5 meter hoog worden. In jouw dierentuin rekt hij zijn lange nek naar de boomkruinen en biedt bezoekers een onvergelijkelijk gezicht.'},
   fr: {name: 'Girafe masa\u00ef', desc: 'La girafe masa\u00ef est la plus grande de toutes les sous-esp\u00e8ces de girafes avec un motif de taches irr\u00e9gulier unique. Elle vit dans les savanes d\'Afrique de l\'Est et peut mesurer plus de 5 m\u00e8tres. Dans ton zoo, elle \u00e9tend son long cou vers la cime des arbres et offre aux visiteurs un spectacle incomparable.'},
   es: {name: 'Jirafa masa\u00ed', desc: 'La jirafa masa\u00ed es la m\u00e1s alta de todas las subespecies de jirafas con un patr\u00f3n de manchas irregular \u00fanico. Vive en las sabanas de \u00c1frica Oriental y puede medir m\u00e1s de 5 metros. En tu zoo, estira su largo cuello hacia las copas de los \u00e1rboles y ofrece a los visitantes una vista incomparable.'}},
  {animalId: 223, da: {name: 'Oryx', desc: 'Oryxen er en majest\u00e6tisk \u00f8rkenantilope med lange, lige horn og en sl\u00e5ende hvid og sort ansigtsmaske. Den er perfekt tilpasset livet i \u00f8rkenens ekstreme varme. I din zoo vandrer den elegant gennem sit areal og imponerer bes\u00f8gende med sine spektakul\u00e6re horn.'},
   nl: {name: 'Oryx', desc: 'De oryx is een majestueuze woestijnantilope met lange, rechte horens en een opvallend wit-zwart gezichtsmasker. Hij is perfect aangepast aan het leven in de extreme hitte van de woestijn. In jouw dierentuin wandelt hij elegant door zijn terrein en maakt indruk op bezoekers met zijn spectaculaire horens.'},
   fr: {name: 'Oryx', desc: 'L\'oryx est une majestueuse antilope du d\u00e9sert aux longues cornes droites et au masque facial noir et blanc saisissant. Il est parfaitement adapt\u00e9 \u00e0 la vie dans la chaleur extr\u00eame du d\u00e9sert. Dans ton zoo, il d\u00e9ambule \u00e9l\u00e9gamment dans son enclos et impressionne les visiteurs par ses cornes spectaculaires.'},
   es: {name: '\u00d3rix', desc: 'El \u00f3rix es un majestuoso ant\u00edlope del desierto con largos cuernos rectos y una llamativa m\u00e1scara facial blanca y negra. Est\u00e1 perfectamente adaptado a la vida en el calor extremo del desierto. En tu zoo, pasea elegantemente por su recinto y asombra a los visitantes con sus espectaculares cuernos.'}},
  {animalId: 224, da: {name: 'P\u00e5fugl', desc: 'P\u00e5fuglen er en af naturens mest pr\u00e6gtige fugle, hvor hannen har en overd\u00e5dig halefjerdragt med iridescerende \u00f8jepletter. Den stammer fra Indien og Sri Lanka. I din zoo sl\u00e5r hannen sit hjul og spreder sin fantastiske fjerdragt til bes\u00f8gendes henrykkelse.'},
   nl: {name: 'Pauw', desc: 'De pauw is een van de prachtigste vogels in de natuur, waarbij het mannetje een weelderige staart heeft met iriserende oogvlekken. Hij stamt uit India en Sri Lanka. In jouw dierentuin slaat het mannetje zijn rad en spreidt zijn fantastische verenkleed tot verrukking van de bezoekers.'},
   fr: {name: 'Paon', desc: 'Le paon est l\'un des oiseaux les plus somptueux de la nature, le m\u00e2le arborant une queue somptueuse aux ocelles iridescentes. Il est originaire d\'Inde et du Sri Lanka. Dans ton zoo, le m\u00e2le fait la roue et d\u00e9ploie son fantastique plumage pour le plus grand ravissement des visiteurs.'},
   es: {name: 'Pavo real', desc: 'El pavo real es una de las aves m\u00e1s magn\u00edficas de la naturaleza, con el macho luciendo una cola exuberante con ocelos iridiscentes. Es originario de la India y Sri Lanka. En tu zoo, el macho despliega su abanico y exhibe su fant\u00e1stico plumaje para deleite de los visitantes.'}},
  {animalId: 225, da: {name: 'Quokka', desc: 'Quokkaen er et lille pungdyr fra det vestlige Australien, der er ber\u00f8mt for sit evige smil. Den er venlig og nysgerrig og har n\u00e6sten ingen frygt for mennesker. I din zoo hopper den glad rundt og byder bes\u00f8gende velkommen med sit uimodst\u00e5eligt smil.'},
   nl: {name: 'Quokka', desc: 'De quokka is een klein buideldier uit het westen van Australi\u00eb dat beroemd is om zijn eeuwige glimlach. Hij is vriendelijk en nieuwsgierig en heeft bijna geen angst voor mensen. In jouw dierentuin huppelt hij vrolijk rond en verwelkomt bezoekers met zijn onweerstaanbare glimlach.'},
   fr: {name: 'Quokka', desc: 'Le quokka est un petit marsupial d\'Australie occidentale c\u00e9l\u00e8bre pour son sourire perp\u00e9tuel. Il est amical et curieux et n\'a presque aucune peur de l\'homme. Dans ton zoo, il sautille joyeusement et accueille les visiteurs avec son sourire irr\u00e9sistible.'},
   es: {name: 'Quokka', desc: 'El quokka es un peque\u00f1o marsupial del oeste de Australia famoso por su eterna sonrisa. Es amigable y curioso y casi no tiene miedo de los humanos. En tu zoo, salta alegremente y da la bienvenida a los visitantes con su irresistible sonrisa.'}},
  {animalId: 226, da: {name: 'Rensdyr', desc: 'Rensdyret er et ikonisk dyr fra de arktiske regioner, kendt for sine store gevirer, som begge k\u00f8n b\u00e6rer. Det er tilpasset det barske polklima og kan finde f\u00f8de under sneen. I din zoo vandrer det roligt gennem sit sned\u00e6kkede areal og minder bes\u00f8gende om vinterens magi.'},
   nl: {name: 'Rendier', desc: 'Het rendier is een iconisch dier uit de arctische gebieden, bekend om zijn grote gewei dat zowel mannetjes als vrouwtjes dragen. Het is aangepast aan het barre poolklimaat en kan voedsel vinden onder de sneeuw. In jouw dierentuin wandelt het rustig door zijn besneeuwde terrein en herinnert bezoekers aan de magie van de winter.'},
   fr: {name: 'Renne', desc: 'Le renne est un animal embl\u00e9matique des r\u00e9gions arctiques, connu pour ses grands bois port\u00e9s par les deux sexes. Il est adapt\u00e9 au rude climat polaire et peut trouver sa nourriture sous la neige. Dans ton zoo, il se prom\u00e8ne tranquillement dans son enclos enneig\u00e9 et rappelle aux visiteurs la magie de l\'hiver.'},
   es: {name: 'Reno', desc: 'El reno es un animal ic\u00f3nico de las regiones \u00e1rticas, conocido por sus grandes astas que portan ambos sexos. Est\u00e1 adaptado al duro clima polar y puede encontrar alimento bajo la nieve. En tu zoo, pasea tranquilamente por su recinto nevado y recuerda a los visitantes la magia del invierno.'}},
  {animalId: 227, da: {name: 'K\u00e6mpeskildpadde', desc: 'K\u00e6mpeskildpadden kan leve i over 100 \u00e5r og veje mere end 400 kg, hvilket g\u00f8r den til en af verdens st\u00f8rste skildpadder. Den lever p\u00e5 \u00f8er som Gal\u00e1pagos og Seychellerne. I din zoo bev\u00e6ger den sig langsomt og majest\u00e6tisk og fascinerer bes\u00f8gende med sin imponerende alder og st\u00f8rrelse.'},
   nl: {name: 'Reuzenschildpad', desc: 'De reuzenschildpad kan meer dan 100 jaar oud worden en meer dan 400 kg wegen, waarmee hij een van de grootste schildpadden ter wereld is. Hij leeft op eilanden zoals de Gal\u00e1pagos en de Seychellen. In jouw dierentuin beweegt hij zich langzaam en majestueus en fascineert bezoekers met zijn imposante leeftijd en grootte.'},
   fr: {name: 'Tortue g\u00e9ante', desc: 'La tortue g\u00e9ante peut vivre plus de 100 ans et peser plus de 400 kg, ce qui en fait l\'une des plus grandes tortues du monde. Elle vit sur des \u00eeles comme les Gal\u00e1pagos et les Seychelles. Dans ton zoo, elle se d\u00e9place lentement et majestueusement et fascine les visiteurs par son \u00e2ge et sa taille impressionnants.'},
   es: {name: 'Tortuga gigante', desc: 'La tortuga gigante puede vivir m\u00e1s de 100 a\u00f1os y pesar m\u00e1s de 400 kg, siendo una de las tortugas m\u00e1s grandes del mundo. Vive en islas como las Gal\u00e1pagos y las Seychelles. En tu zoo, se mueve lenta y majestuosamente y fascina a los visitantes con su impresionante edad y tama\u00f1o.'}},
  {animalId: 228, da: {name: 'Gal\u00e1pagos roset-leguaan', desc: 'Gal\u00e1pagos roset-leguanen er en sj\u00e6lden og enest\u00e5ende krybdyr med en lyser\u00f8d farvetone, der kun findes p\u00e5 Isabela-\u00f8en. Den blev f\u00f8rst videnskabeligt beskrevet i 2009. I din zoo bader den sig i solen p\u00e5 klipperne og fanger bes\u00f8gendes opm\u00e6rksomhed med sin us\u00e6dvanlige farve.'},
   nl: {name: 'Roze Gal\u00e1pagos-leguaan', desc: 'De roze Gal\u00e1pagos-leguaan is een zeldzaam en uniek reptiel met een roze kleur dat alleen voorkomt op het eiland Isabela. Hij werd pas in 2009 wetenschappelijk beschreven. In jouw dierentuin badt hij in de zon op de rotsen en trekt de aandacht van bezoekers met zijn ongewone kleur.'},
   fr: {name: 'Iguane rose des Gal\u00e1pagos', desc: 'L\'iguane rose des Gal\u00e1pagos est un reptile rare et unique \u00e0 la teinte ros\u00e9e que l\'on ne trouve que sur l\'\u00eele Isabela. Il n\'a \u00e9t\u00e9 scientifiquement d\u00e9crit qu\'en 2009. Dans ton zoo, il se pr\u00e9lasse au soleil sur les rochers et attire l\'attention des visiteurs par sa couleur inhabituelle.'},
   es: {name: 'Iguana rosada de Gal\u00e1pagos', desc: 'La iguana rosada de Gal\u00e1pagos es un reptil raro y \u00fanico de tonalidad rosada que solo se encuentra en la isla Isabela. Fue descrita cient\u00edficamente reci\u00e9n en 2009. En tu zoo, toma el sol sobre las rocas y capta la atenci\u00f3n de los visitantes con su inusual color.'}},
  {animalId: 229, da: {name: 'R\u00f8dt k\u00e6mpekanguru', desc: 'Det r\u00f8de k\u00e6mpekanguru er det st\u00f8rste pungdyr i verden og kan st\u00e5 over 2 meter h\u00f8j. Det lever i Australiens t\u00f8rre indland og kan hoppe over 9 meter i et enkelt spring. I din zoo hopper det kraftfuldt gennem sin indhegning og begejstrer bes\u00f8gende med sine atletiske spring.'},
   nl: {name: 'Rood reuzenkangoeroe', desc: 'De rode reuzenkangoeroe is het grootste buideldier ter wereld en kan meer dan 2 meter hoog staan. Hij leeft in het droge binnenland van Australi\u00eb en kan meer dan 9 meter ver springen in een enkele sprong. In jouw dierentuin springt hij krachtig door zijn verblijf en begeistert bezoekers met zijn atletische sprongen.'},
   fr: {name: 'Grand kangourou roux', desc: 'Le grand kangourou roux est le plus grand marsupial du monde et peut mesurer plus de 2 m\u00e8tres debout. Il vit dans l\'arri\u00e8re-pays aride d\'Australie et peut bondir sur plus de 9 m\u00e8tres en un seul saut. Dans ton zoo, il bondit puissamment dans son enclos et enthousiasme les visiteurs par ses sauts athl\u00e9tiques.'},
   es: {name: 'Canguro rojo', desc: 'El canguro rojo es el marsupial m\u00e1s grande del mundo y puede medir m\u00e1s de 2 metros de pie. Vive en el interior \u00e1rido de Australia y puede saltar m\u00e1s de 9 metros en un solo salto. En tu zoo, salta con fuerza por su recinto y entusiasma a los visitantes con sus saltos atl\u00e9ticos.'}},
  {animalId: 230, da: {name: 'Saigaantilope', desc: 'Saigaantilopen er en sj\u00e6lden antilope fra de centralasiatiske stepper med en us\u00e6dvanlig stor og oppustelig n\u00e6se. Dens n\u00e6se filtrerer st\u00f8v om sommeren og opvarmer luften om vinteren. I din zoo vandrer den over sit steppelandskab og fascinerer bes\u00f8gende med sin unikke n\u00e6se.'},
   nl: {name: 'Saiga', desc: 'De saiga is een zeldzame antilope uit de Centraal-Aziatische steppen met een ongewoon grote en opblaasbare neus. Zijn neus filtert stof in de zomer en verwarmt de lucht in de winter. In jouw dierentuin zwerft hij over zijn steppelandschap en fascineert bezoekers met zijn unieke neus.'},
   fr: {name: 'Sa\u00efga', desc: 'Le sa\u00efga est une antilope rare des steppes d\'Asie centrale au nez inhabituellement grand et gonflable. Son nez filtre la poussi\u00e8re en \u00e9t\u00e9 et r\u00e9chauffe l\'air en hiver. Dans ton zoo, il arpente son paysage de steppe et fascine les visiteurs par son nez unique.'},
   es: {name: 'Saiga', desc: 'El saiga es un ant\u00edlope raro de las estepas de Asia Central con una nariz inusualmente grande e inflable. Su nariz filtra el polvo en verano y calienta el aire en invierno. En tu zoo, recorre su paisaje estepario y fascina a los visitantes con su nariz \u00fanica.'}},
  {animalId: 231, da: {name: 'Sortfodet kat', desc: 'Den sortfodede kat er Afrikas mindste vildkat og vejer kun omkring 1,5 kg. Trods sin lille st\u00f8rrelse er den en af verdens mest effektive j\u00e6gere med en succesrate p\u00e5 60 procent. I din zoo jager den legesygt efter leget\u00f8j og overrasker bes\u00f8gende med sin energiske adf\u00e6rd.'},
   nl: {name: 'Zwartvoetenkat', desc: 'De zwartvoetenkat is de kleinste wilde kat van Afrika en weegt slechts ongeveer 1,5 kg. Ondanks zijn kleine formaat is hij een van de meest effici\u00ebnte jagers ter wereld met een succespercentage van 60 procent. In jouw dierentuin jaagt hij speels op speeltjes en verrast bezoekers met zijn energieke gedrag.'},
   fr: {name: 'Chat \u00e0 pieds noirs', desc: 'Le chat \u00e0 pieds noirs est le plus petit f\u00e9lin sauvage d\'Afrique et ne p\u00e8se qu\'environ 1,5 kg. Malgr\u00e9 sa petite taille, c\'est l\'un des chasseurs les plus efficaces au monde avec un taux de r\u00e9ussite de 60 pour cent. Dans ton zoo, il chasse de mani\u00e8re enjou\u00e9e ses jouets et surprend les visiteurs par son comportement \u00e9nergique.'},
   es: {name: 'Gato de pies negros', desc: 'El gato de pies negros es el felino salvaje m\u00e1s peque\u00f1o de \u00c1frica y pesa solo unos 1,5 kg. A pesar de su peque\u00f1o tama\u00f1o, es uno de los cazadores m\u00e1s eficientes del mundo con una tasa de \u00e9xito del 60 por ciento. En tu zoo, caza juguetonamente sus juguetes y sorprende a los visitantes con su en\u00e9rgico comportamiento.'}},
  {animalId: 232, da: {name: 'Sekret\u00e6rfugl', desc: 'Sekret\u00e6rfuglen er en stor rovfugl fra Afrika, der er unik, fordi den jager til fods. Med sine lange ben tramper den p\u00e5 slanger og andre byttedyr. I din zoo patruljerer den stolt sit areal og demonstrerer sin karakteristiske jagtmetode til bes\u00f8gendes beundring.'},
   nl: {name: 'Secretarisvogel', desc: 'De secretarisvogel is een grote roofvogel uit Afrika die uniek is omdat hij te voet jaagt. Met zijn lange poten stampt hij op slangen en andere prooidieren. In jouw dierentuin patrouilleert hij trots zijn terrein en demonstreert zijn karakteristieke jachtmethode tot bewondering van de bezoekers.'},
   fr: {name: 'Messager serpentaire', desc: 'Le messager serpentaire est un grand rapace d\'Afrique unique en son genre car il chasse \u00e0 pied. Avec ses longues pattes, il pi\u00e9tine serpents et autres proies. Dans ton zoo, il patrouille fi\u00e8rement dans son enclos et d\u00e9montre sa m\u00e9thode de chasse caract\u00e9ristique \u00e0 l\'admiration des visiteurs.'},
   es: {name: 'Secretario', desc: 'El secretario es una gran rapaz de \u00c1frica que es \u00fanica porque caza a pie. Con sus largas patas, pisotea serpientes y otras presas. En tu zoo, patrulla orgullosamente su recinto y demuestra su caracter\u00edstico m\u00e9todo de caza para admiraci\u00f3n de los visitantes.'}},
  {animalId: 233, da: {name: 'Serval', desc: 'Servalen er en slank afrikansk vildkat med us\u00e6dvanligt lange ben og store \u00f8rer, der giver den et fremragende h\u00f8resans. Den kan springe op til 3 meter i h\u00f8jden for at fange fugle. I din zoo viser den sin utrolige springevne og begejstrer bes\u00f8gende med sin elegante jagt.'},
   nl: {name: 'Serval', desc: 'De serval is een slanke Afrikaanse wilde kat met ongewoon lange poten en grote oren die hem een uitstekend gehoor geven. Hij kan tot 3 meter hoog springen om vogels te vangen. In jouw dierentuin toont hij zijn ongelooflijke springvermogen en begeistert bezoekers met zijn elegante jacht.'},
   fr: {name: 'Serval', desc: 'Le serval est un f\u00e9lin africain \u00e9lanc\u00e9 aux pattes inhabituellement longues et aux grandes oreilles lui conf\u00e9rant une ou\u00efe exceptionnelle. Il peut bondir jusqu\'\u00e0 3 m\u00e8tres de haut pour attraper des oiseaux. Dans ton zoo, il montre son incroyable capacit\u00e9 de saut et enthousiasme les visiteurs par sa chasse \u00e9l\u00e9gante.'},
   es: {name: 'Serval', desc: 'El serval es un felino africano esbelto con patas inusualmente largas y grandes orejas que le proporcionan un o\u00eddo excelente. Puede saltar hasta 3 metros de altura para atrapar aves. En tu zoo, demuestra su incre\u00edble capacidad de salto y entusiasma a los visitantes con su elegante caza.'}},
  {animalId: 234, da: {name: 'Amerikansk gr\u00e6vling', desc: 'Den amerikanske gr\u00e6vling er et robust og kompakt rovdyr med en bred krop og st\u00e6rke gravekl\u00f8r. Den lever i de nordamerikanske pr\u00e6rier og er en fremragende graver. I din zoo graver den energisk tunneler i sit areal og fascinerer bes\u00f8gende med sin styrke.'},
   nl: {name: 'Amerikaanse das', desc: 'De Amerikaanse das is een robuust en compact roofdier met een breed lichaam en sterke graafklauwen. Hij leeft in de Noord-Amerikaanse prairies en is een uitstekende graver. In jouw dierentuin graaft hij energiek tunnels in zijn terrein en fascineert bezoekers met zijn kracht.'},
   fr: {name: 'Blaireau am\u00e9ricain', desc: 'Le blaireau am\u00e9ricain est un pr\u00e9dateur robuste et compact au corps large et aux griffes puissantes pour creuser. Il vit dans les prairies nord-am\u00e9ricaines et est un excellent fouisseur. Dans ton zoo, il creuse \u00e9nergiquement des tunnels dans son enclos et fascine les visiteurs par sa force.'},
   es: {name: 'Tej\u00f3n americano', desc: 'El tej\u00f3n americano es un depredador robusto y compacto con un cuerpo ancho y fuertes garras para excavar. Vive en las praderas norteamericanas y es un excelente excavador. En tu zoo, excava en\u00e9rgicamente t\u00faneles en su recinto y fascina a los visitantes con su fuerza.'}},
  {animalId: 235, da: {name: 'S\u00f8lvgalago', desc: 'S\u00f8lvgalagoen er en stor nataktiv primat fra \u00d8stafrika med store \u00f8jne og bl\u00f8de, s\u00f8lvfarvede pels. Den kommunikerer med h\u00f8je skrig i natten. I din zoo klatrer den beh\u00e6ndigt i grenene ved m\u00f8rkets frembrud og fortryller bes\u00f8gende med sine store, lysende \u00f8jne.'},
   nl: {name: 'Grote galago', desc: 'De grote galago is een grote nachtactieve primaat uit Oost-Afrika met grote ogen en een zachte, zilverkleurige vacht. Hij communiceert met luide kreten in de nacht. In jouw dierentuin klimt hij behendig in de takken bij het vallen van de avond en betovert bezoekers met zijn grote, glanzende ogen.'},
   fr: {name: 'Grand galago', desc: 'Le grand galago est un grand primate nocturne d\'Afrique de l\'Est aux grands yeux et au pelage doux et argent\u00e9. Il communique par des cris per\u00e7ants dans la nuit. Dans ton zoo, il grimpe habilement dans les branches \u00e0 la tomb\u00e9e de la nuit et enchante les visiteurs par ses grands yeux brillants.'},
   es: {name: 'G\u00e1lago mayor', desc: 'El g\u00e1lago mayor es un gran primate nocturno de \u00c1frica Oriental con grandes ojos y un pelaje suave y plateado. Se comunica con fuertes gritos en la noche. En tu zoo, trepa h\u00e1bilmente por las ramas al caer la noche y encanta a los visitantes con sus grandes ojos brillantes.'}},
  {animalId: 236, da: {name: 'Steppesk\u00e6ludyr', desc: 'Steppesk\u00e6ludyret er et sj\u00e6ldent og truet pattedyr med et rustningsagtigt sk\u00e6l af keratin. Det ruller sig sammen til en kugle som forsvar mod rovdyr. I din zoo roder det forsigtigt i jorden efter myrer og termitter og fascinerer bes\u00f8gende med sit unikke panser.'},
   nl: {name: 'Steppe-schubdier', desc: 'Het steppe-schubdier is een zeldzaam en bedreigd zoogdier met een pantserachtige schubben van keratine. Hij rolt zich op tot een bal als verdediging tegen roofdieren. In jouw dierentuin snuffelt hij voorzichtig in de grond naar mieren en termieten en fascineert bezoekers met zijn unieke pantser.'},
   fr: {name: 'Pangolin des steppes', desc: 'Le pangolin des steppes est un mammif\u00e8re rare et menac\u00e9 dot\u00e9 d\'\u00e9cailles en k\u00e9ratine formant une armure. Il se roule en boule pour se d\u00e9fendre contre les pr\u00e9dateurs. Dans ton zoo, il fouille prudemment le sol \u00e0 la recherche de fourmis et de termites et fascine les visiteurs par sa cuirasse unique.'},
   es: {name: 'Pangol\u00edn de la estepa', desc: 'El pangol\u00edn de la estepa es un mam\u00edfero raro y amenazado con escamas de queratina que forman una armadura. Se enrolla en una bola para defenderse de los depredadores. En tu zoo, hurga con cuidado en el suelo buscando hormigas y termitas y fascina a los visitantes con su coraza \u00fanica.'}},
  {animalId: 237, da: {name: 'Burchells zebra', desc: 'Burchells zebra er den mest udbredte zebraart med brede, sorte og hvide striber, der er unikke for hvert individ. Den lever i store flokke p\u00e5 de \u00f8stafrikanske savanner. I din zoo galopperer den livligt i flok og begejstrer bes\u00f8gende med sit i\u00f8jnefaldende stribem\u00f8nster.'},
   nl: {name: 'Burchells zebra', desc: 'De Burchells zebra is de meest voorkomende zebrasoort met brede, zwart-witte strepen die uniek zijn voor elk individu. Hij leeft in grote kuddes op de Oost-Afrikaanse savannen. In jouw dierentuin galoppeert hij levendig in de kudde en begeistert bezoekers met zijn opvallende streeppatroon.'},
   fr: {name: 'Z\u00e8bre des plaines', desc: 'Le z\u00e8bre des plaines est l\'esp\u00e8ce de z\u00e8bre la plus r\u00e9pandue avec de larges rayures noires et blanches uniques \u00e0 chaque individu. Il vit en grands troupeaux dans les savanes d\'Afrique de l\'Est. Dans ton zoo, il galope vivement en troupeau et enthousiasme les visiteurs par ses rayures spectaculaires.'},
   es: {name: 'Cebra de Burchell', desc: 'La cebra de Burchell es la especie de cebra m\u00e1s com\u00fan con amplias rayas blancas y negras \u00fanicas para cada individuo. Vive en grandes manadas en las sabanas de \u00c1frica Oriental. En tu zoo, galopa animadamente en manada y entusiasma a los visitantes con sus espectaculares rayas.'}},
  {animalId: 238, da: {name: 'Sidestribejakhund', desc: 'Sidestribejakhunden er en lille, smuk sjakal fra Afrika med en karakteristisk hvid stribe langs flanken. Den lever i par og er aktiv fra skumring til daggry. I din zoo strejfer den forsigtigt rundt ved skumringstid og fascinerer bes\u00f8gende med sin smukke pels.'},
   nl: {name: 'Gestreepte jakhals', desc: 'De gestreepte jakhals is een kleine, mooie jakhals uit Afrika met een karakteristieke witte streep langs de flanken. Hij leeft in paren en is actief van schemering tot dageraad. In jouw dierentuin zwerft hij voorzichtig rond bij schemering en fascineert bezoekers met zijn prachtige vacht.'},
   fr: {name: 'Chacal \u00e0 flancs ray\u00e9s', desc: 'Le chacal \u00e0 flancs ray\u00e9s est un petit chacal \u00e9l\u00e9gant d\'Afrique avec une bande blanche caract\u00e9ristique le long des flancs. Il vit en couples et est actif du cr\u00e9puscule \u00e0 l\'aube. Dans ton zoo, il r\u00f4de prudemment au cr\u00e9puscule et fascine les visiteurs par son beau pelage.'},
   es: {name: 'Chacal rayado', desc: 'El chacal rayado es un peque\u00f1o y hermoso chacal de \u00c1frica con una franja blanca caracter\u00edstica a lo largo de los flancos. Vive en parejas y es activo del crep\u00fasculo al amanecer. En tu zoo, merodea con cautela al atardecer y fascina a los visitantes con su hermoso pelaje.'}},
  {animalId: 239, da: {name: 'Tigerbrud', desc: 'Tigerbruden er et sj\u00e6ldent og farverigt lille rovdyr fra Centralasien med et smukt marmoreret pelsm\u00f8nster. Den lever i bjergskove og jager sm\u00e5pattedyr. I din zoo klatrer den beh\u00e6ndigt i sit anl\u00e6g og henrykker bes\u00f8gende med sit unikke og smukke pelsm\u00f8nster.'},
   nl: {name: 'Marmerbunzing', desc: 'De marmerbunzing is een zeldzaam en kleurrijk klein roofdier uit Centraal-Azi\u00eb met een prachtig gemarmerd vachtpatroon. Hij leeft in bergbossen en jaagt op kleine zoogdieren. In jouw dierentuin klimt hij behendig in zijn verblijf en bekoort bezoekers met zijn unieke en prachtige vachtpatroon.'},
   fr: {name: 'Putois marbr\u00e9', desc: 'Le putois marbr\u00e9 est un petit pr\u00e9dateur rare et color\u00e9 d\'Asie centrale au magnifique pelage marbr\u00e9. Il vit dans les for\u00eats montagneuses et chasse les petits mammif\u00e8res. Dans ton zoo, il grimpe habilement dans son installation et ravit les visiteurs par son motif de pelage unique et magnifique.'},
   es: {name: 'Tur\u00f3n jaspeado', desc: 'El tur\u00f3n jaspeado es un peque\u00f1o depredador raro y colorido de Asia Central con un hermoso patr\u00f3n de pelaje marmolado. Vive en bosques de monta\u00f1a y caza peque\u00f1os mam\u00edferos. En tu zoo, trepa h\u00e1bilmente por su instalaci\u00f3n y encanta a los visitantes con su patr\u00f3n de pelaje \u00fanico y hermoso.'}},
  {animalId: 240, da: {name: 'Dv\u00e6rgflamingo', desc: 'Dv\u00e6rgflamingoen er den mindste flamingoart og lever i store kolonier ved alkaliske s\u00f8er i Afrika og Indien. Dens lyser\u00f8de fjerdragt er endnu mere intens end den store flamingos. I din zoo st\u00e5r den i store flokke i sit bassin og skaber et betagende lyser\u00f8dt syn.'},
   nl: {name: 'Kleine flamingo', desc: 'De kleine flamingo is de kleinste flamingosoort en leeft in grote kolonies bij alkalische meren in Afrika en India. Zijn roze verenkleed is nog intenser dan dat van de grote flamingo. In jouw dierentuin staat hij in grote groepen in zijn bassin en cre\u00ebert een betoverend roze schouwspel.'},
   fr: {name: 'Petit flamant', desc: 'Le petit flamant est la plus petite esp\u00e8ce de flamant et vit en grandes colonies pr\u00e8s des lacs alcalins d\'Afrique et d\'Inde. Son plumage rose est encore plus intense que celui du grand flamant. Dans ton zoo, il se tient en grands groupes dans son bassin et cr\u00e9e un spectacle rose envo\u00fbtant.'},
   es: {name: 'Flamenco menor', desc: 'El flamenco menor es la especie de flamenco m\u00e1s peque\u00f1a y vive en grandes colonias junto a lagos alcalinos de \u00c1frica e India. Su plumaje rosa es a\u00fan m\u00e1s intenso que el del flamenco com\u00fan. En tu zoo, se mantiene en grandes grupos en su estanque y crea un cautivador espect\u00e1culo rosa.'}},
  {animalId: 241, da: {name: 'Gal\u00e1pagos landleguaan', desc: 'Gal\u00e1pagos landleguanen er et stort, robust krybdyr, der kun findes p\u00e5 Gal\u00e1pagos\u00f8erne. Den lever af kaktusser og blade og kan blive over 50 \u00e5r gammel. I din zoo bader den sig i solen og nikker langsomt med hovedet, mens bes\u00f8gende beundrer dens urokkelige ro.'},
   nl: {name: 'Gal\u00e1pagos-leguaan', desc: 'De Gal\u00e1pagos-leguaan is een groot, robuust reptiel dat alleen voorkomt op de Gal\u00e1pagoseilanden. Hij leeft van cactussen en bladeren en kan meer dan 50 jaar oud worden. In jouw dierentuin badt hij in de zon en knikt langzaam met zijn hoofd terwijl bezoekers zijn onverstoorbare rust bewonderen.'},
   fr: {name: 'Iguane terrestre des Gal\u00e1pagos', desc: 'L\'iguane terrestre des Gal\u00e1pagos est un grand reptile robuste que l\'on ne trouve que sur les \u00eeles Gal\u00e1pagos. Il se nourrit de cactus et de feuilles et peut vivre plus de 50 ans. Dans ton zoo, il se pr\u00e9lasse au soleil et hoche lentement la t\u00eate tandis que les visiteurs admirent son calme imperturbable.'},
   es: {name: 'Iguana terrestre de Gal\u00e1pagos', desc: 'La iguana terrestre de Gal\u00e1pagos es un reptil grande y robusto que solo se encuentra en las islas Gal\u00e1pagos. Se alimenta de cactus y hojas y puede vivir m\u00e1s de 50 a\u00f1os. En tu zoo, toma el sol y mueve lentamente la cabeza mientras los visitantes admiran su inquebrantable calma.'}},
];

const langs = ['da', 'nl', 'fr', 'es'];

const sqlRows = [];
for (const animal of data) {
  for (const lang of langs) {
    const name = animal[lang].name.replace(/'/g, "''");
    const desc = animal[lang].desc.replace(/'/g, "''");
    sqlRows.push(`(${id}, ${animal.animalId}, '${lang}', '${name}', '${desc}')`);
    id++;
  }
}

console.log(`Generated ${sqlRows.length} rows, IDs 721 to ${id - 1}`);

const sql = `\n-- Biome 100 & 200: animaltext rows for da/nl/fr/es (IDs 721-1044)\nINSERT INTO \`animaltext\` (\`id\`, \`animalId\`, \`languageCode\`, \`animalName\`, \`animalDescription\`) VALUES\n${sqlRows.join(',\n')};\n`;

fs.appendFileSync(filePath, sql, 'utf8');
console.log('SQL appended successfully');
